_OCR_OK = None


def ocr_available(refresh=False):
    """True nếu đọc được PDF scan / ảnh: có pytesseract, pypdfium2 và chạy được chương trình Tesseract.
    Kết quả được nhớ lại vì mỗi lần kiểm tra phải chạy chương trình Tesseract (chậm, nhất là trên Windows)."""
    global _OCR_OK
    if _OCR_OK is not None and not refresh:
        return _OCR_OK
    if pytesseract is None or pdfium is None:
        _OCR_OK = False
        return False
    try:
        pytesseract.get_tesseract_version()
        _OCR_OK = True
    except Exception:
        _OCR_OK = False
    return _OCR_OK


