# 2. TẬP LƯU TRỮ DỮ LIỆU RIÊNG TRÊN DESKTOP / MÁY CHỦ HOST (DATA REPOSITORY)
# ==============================================================================
class DedicatedDataStore:
    """Quản lý tập lưu trữ dữ liệu riêng (SQLite + JSON + Cây thư mục Host)."""

    def __init__(self, base_dir=None):
        app_dir = get_app_dir()
        self.config_file = os.path.join(app_dir, "config_desktop.json")
        saved_dir = None
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, "r", encoding="utf-8") as f:
                    saved_dir = json.load(f).get("data_dir")
            except Exception:
                pass
        default_sub = os.path.join(app_dir, "DATA_LUU_TRU_HONG_THIEN")
        if not os.path.exists(default_sub):
            alt_sub = os.path.join(app_dir, "..", "intermediate", "HongThien_HaiQuan_Desktop_App", "DATA_LUU_TRU_HONG_THIEN")
            if os.path.exists(alt_sub):
                default_sub = os.path.abspath(alt_sub)
        self.base_dir = base_dir or saved_dir or default_sub
        self.ensure_directories()
        self.weights_db = {}
        self.erp_catalog = []
        self.erp_map = {}
        self.kodi_items = list(DEFAULT_KODI_ITEMS)
        self.tesa_items = list(DEFAULT_TESA_ITEMS)
        self.item_mem = {}
        self.read_fixes = []  # nhật ký các lần người dùng sửa số liệu máy đọc sai từ PO (khách, trường, đọc sai, đúng, dòng PO)
        self.custom_profiles = {}
        self.custom_items = {}
        self.company = {}  # thông tin công ty người dùng đã sửa (Cài đặt); trống = dùng mặc định
        self.profile_overrides = {}  # chỗ người dùng đã sửa trên 3 khách có sẵn (mục Khách hàng)
        self.records = []
        self._sigs, self._loaded_ids = {}, set()
        self.data_tong, self._dt_cache, self._dt_idx, self._dt_cust = [], {}, None, {}
        self.load_all()

    # ---- người dùng của máy này (lưu ở file cấu hình cạnh phần mềm, KHÔNG nằm trong thư mục dùng chung) ----------
    def user_name(self):
        try:
            with open(self.config_file, "r", encoding="utf-8") as f:
                return str(json.load(f).get("user_name") or "").strip()
        except Exception:
            return ""

    def set_user_name(self, name):
        try:
            with open(self.config_file, "r", encoding="utf-8") as f:
                cfg = json.load(f)
        except Exception:
            cfg = {}
        cfg["user_name"] = str(name or "").strip()
        if "data_dir" not in cfg:
            cfg["data_dir"] = self.base_dir
        with open(self.config_file, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)

    def customer_owner(self, key):
        return str((PROFILES.get(key) or {}).get("owner") or "").strip()

    def foreign_owner(self, key):
        """Tên nhân viên phụ trách khách `key` nếu KHÔNG phải người dùng máy này (cả hai đã nhập tên); ngược lại rỗng."""
        owner, me = self.customer_owner(key), self.user_name()
        return owner if owner and me and owner.casefold() != me.casefold() else ""

    def customs_root(self):
        """Thư mục hồ sơ hải quan (chứa thư mục từng khách). Nếu thư mục dữ liệu chính là HAI_QUAN thì dùng luôn nó."""
        if os.path.basename(os.path.normpath(self.base_dir)).upper() == CUSTOMS_ROOT:
            return self.base_dir
        return os.path.join(self.base_dir, CUSTOMS_ROOT)

    def rel_to_abs(self, rel):
        """Đường dẫn tương đối kiểu HAI_QUAN/<Khách>/... -> tuyệt đối (không lặp HAI_QUAN khi thư mục dữ liệu đã là HAI_QUAN)."""
        pre = CUSTOMS_ROOT + os.sep
        r = str(rel).replace("/", os.sep)
        if r.startswith(pre) or r.startswith(CUSTOMS_ROOT + "/"):
            return os.path.join(self.customs_root(), r[len(pre):])
        return os.path.join(self.base_dir, r)

    def ensure_directories(self):
        os.makedirs(self.base_dir, exist_ok=True)
        os.makedirs(self.customs_root(), exist_ok=True)  # chỉ một thư mục gốc cho toàn bộ hồ sơ hải quan
        self.catalog_file = os.path.join(self.base_dir, "master_catalog.json")
        self.records_file = os.path.join(self.base_dir, "hongthien_records.json")
        self.sqlite_file = os.path.join(self.base_dir, "hongthien_haiquan.db")
        global TEMPLATE_DIR
        TEMPLATE_DIR = os.path.join(self.base_dir, "MAU_CHUNG_TU")

    def change_base_dir(self, new_dir):
        self.base_dir = os.path.abspath(new_dir)
        try:
            with open(self.config_file, "w", encoding="utf-8") as f:
                json.dump({"data_dir": self.base_dir}, f, ensure_ascii=False, indent=2)
        except Exception:
            pass
        self.ensure_directories()
        self.load_all()

    def load_all(self):
        if not os.path.exists(self.catalog_file) and EMBEDDED_MASTER_CATALOG_B64:
            try:
                raw_bytes = zlib.decompress(base64.b64decode(EMBEDDED_MASTER_CATALOG_B64))
                with open(self.catalog_file, "wb") as f:
                    f.write(raw_bytes)
            except Exception:
                pass
        if os.path.exists(self.catalog_file):
            try:
                with open(self.catalog_file, "r", encoding="utf-8") as f:
                    data = json.load(f)
                self.weights_db = data.get("weights_db", {})
                self.erp_catalog = data.get("erp_catalog", [])
                if data.get("kodi_items"):
                    self.kodi_items = data["kodi_items"]
                if data.get("tesa_items"):
                    self.tesa_items = data["tesa_items"]
                if data.get("item_mem"):
                    self.item_mem = data["item_mem"]
                self.read_fixes = list(data.get("read_fixes") or [])
                self.custom_profiles = data.get("custom_profiles") or {}
                self.custom_items = data.get("custom_items") or {}
                self.company = data.get("company_info") or {}
                self.profile_overrides = data.get("profile_overrides") or {}
            except Exception:
                pass
        self.register_custom_profiles()
        apply_company(self.company)  # luôn áp lại: mỗi kho dữ liệu có thông tin công ty riêng
        apply_profile_overrides(self.profile_overrides)
        self.rebuild_erp_map()

        if os.path.exists(self.records_file):
            try:
                with open(self.records_file, "r", encoding="utf-8") as f:
                    self.records = json.load(f)
            except Exception:
                self.records = []
        self._loaded_ids = {r.get("id") for r in self.records}
        self.dt_load()
        self._note_sigs()
        if not self.records:
            self.records = self.default_seed_records()
            self.save_records()

    def rebuild_erp_map(self):
        self.erp_map = {}
        for it in self.erp_catalog:
            k = clean_str(it.get("ten_sp", ""))
            if k:
                self.erp_map[k] = it.get("ma_sp", "")

    def remember_item_norm(self, name, div, kg, hs=""):
        if not name:
            return
        self.item_mem[name] = {"div": div, "kg": kg, "hs": hs}
        for lst in (self.kodi_items, self.tesa_items, *self.custom_items.values()):
            for it in lst:
                if it["name"] == name:
                    if div > 0:
                        it["div"] = div
                    if kg > 0:
                        it["kg"] = kg
                    if hs:
                        it["hs"] = hs
        self.save_catalog()

    def remember_item_refs(self, cust_key, name, refs):
        """Nhớ mã vật liệu / Inquiry No / Customs No người dùng đã sửa, để lần quét PO sau dùng thay chữ OCR."""
        for it in self.custom_items.get(cust_key, []):
            if it.get("name") == name:
                changed = {k: v for k, v in refs.items() if v and it.get(k) != v}
                if changed:
                    it.update(changed)
                    self.save_catalog()
                return

    def get_item_norm(self, name):
        return self.item_mem.get(name)

    def register_custom_profiles(self):
        """Đưa khách hàng đã học vào PROFILES để mọi biểu mẫu xuất (VAT/PXK/PKL/DNTT) dùng chung."""
        for key, prof in self.custom_profiles.items():
            if key not in BUILTIN_CUSTOMERS:
                PROFILES[key] = build_custom_profile(key, prof)

    def items_for_customer(self, key):
        return {"kodi": self.kodi_items, "tesa": self.tesa_items}.get(key) or self.custom_items.get(key, [])

    def save_learned_customer(self, key, profile_fields, items):
        """Lưu khách hàng mới (đã được người dùng xác nhận) vào master_catalog.json."""
        key = re.sub(r"[^a-z0-9_]", "", (key or "").lower())
        if not key or key in BUILTIN_CUSTOMERS:
            raise ValueError("Mã khách hàng trống hoặc trùng khách có sẵn (shirai/kodi/tesa).")
        prof = build_custom_profile(key, profile_fields)
        self.custom_profiles[key] = prof
        lst = self.custom_items.setdefault(key, [])
        for it in items:
            name = str(it.get("name") or "").strip()
            if not name:
                continue
            hit = next((x for x in lst if (it.get("code") and x.get("code") == it.get("code")) or x["name"] == name), None)
            row = {
                "name": name,
                "code": str(it.get("code") or ""),
                "price": it.get("price") or 0,
                "div": it.get("div") or 0,
                "kg": it.get("kg") or 0,
                "hs": str(it.get("hs") or ""),
                "unit": it.get("unit") or prof["unit"],
                "ten_hq": it.get("ten_hq") or name,
                "tare": prof.get("tare", 0.0),
            }
            if hit:
                hit.update({k: v for k, v in row.items() if v})
            else:
                lst.append(row)
            if row["div"] or row["kg"] or row["hs"]:
                self.item_mem[name] = {"div": row["div"], "kg": row["kg"], "hs": row["hs"]}
        PROFILES[key] = prof
        self.save_catalog()
        return key

    # ---- Cài đặt công ty / sửa thông tin khách (giao diện mới) ----------------------------
    def company_info(self):
        """Thông tin công ty đang dùng (mặc định + phần người dùng đã sửa)."""
        c = dict(COMPANY_DEFAULTS)
        c.update(self.company)
        return c

    def set_company(self, fields):
        """Lưu thông tin công ty; áp ngay cho mọi mẫu xuất. Ném ValueError (tiếng Việt) nếu nhập sai."""
        clean = {k: str(fields.get(k, "")).strip() for k, _ in COMPANY_FIELDS}
        if not clean["name"]:
            raise ValueError("Tên công ty không được để trống.")
        if not re.fullmatch(r"\d{10}(-\d{3})?|\d{13}", clean["mst"]):
            raise ValueError("Mã số thuế gồm 10 chữ số (hoặc 10 số kèm -xxx, hoặc 13 số).")
        if not clean["addr"]:
            raise ValueError("Địa chỉ công ty không được để trống.")
        self.company = clean
        apply_company(self.company)
        apply_profile_overrides(self.profile_overrides)
        self.save_catalog()
        return self.company_info()

    def import_learned(self, data, overwrite=False):
        """Nạp file dữ liệu học (định mức từng mặt hàng: SL/kiện, kg/cái, HS) vào bộ nhớ định mức.
        Mặc định không ghi đè định mức người dùng đã tự nhập. Trả {"them", "ghi_de", "bo_qua"}."""
        cust = data.get("khach_moi") if isinstance(data, dict) else None
        if not isinstance(data, dict) or not (isinstance(data.get("item_mem"), dict) or isinstance(cust, dict)):
            raise ValueError("File này không phải file dữ liệu học của phần mềm (thiếu mục item_mem).")
        res = {"them": 0, "ghi_de": 0, "bo_qua": 0, "khach": "", "mau": 0}
        if isinstance(cust, dict):  # khách học sẵn (hồ sơ + danh mục hàng + file mẫu chứng từ)
            key = re.sub(r"[^a-z0-9_]", "", str(cust.get("key") or "").lower())
            pname = str((cust.get("profile") or {}).get("name") or "").strip().upper()
            same = next((k for k, p in PROFILES.items() if k not in BUILTIN_CUSTOMERS and pname and str(p.get("name") or "").strip().upper() == pname), None)
            if same:  # máy này đã có khách đó (có thể khác mã khách): giữ hồ sơ, chỉ bổ sung mặt hàng mới và file mẫu
                key = same
                lst = self.custom_items.setdefault(key, [])
                for it in cust.get("items") or []:
                    if it.get("name") and not any(x.get("name") == it["name"] or (it.get("code") and x.get("code") == it["code"]) for x in lst):
                        self.save_learned_customer(key, dict(PROFILES[key]), [it])
                res["khach"] = key
                res["mau"] = self.save_templates(key, cust.get("mau") or {}, overwrite)
                if overwrite:
                    self.save_learned_customer(key, {**PROFILES[key], **(cust.get("profile") or {})}, list(cust.get("items") or []))
            elif key and (overwrite or key not in PROFILES):
                self.save_learned_customer(key, dict(cust.get("profile") or {}), list(cust.get("items") or []))
                res["khach"] = key
                res["mau"] = self.save_templates(key, cust.get("mau") or {}, overwrite)
        for name, v in (data.get("item_mem") or {}).items():
            if not isinstance(v, dict) or not str(name).strip():
                continue
            try:
                new = {"div": float(v.get("div") or 0), "kg": float(v.get("kg") or 0), "hs": str(v.get("hs") or "")}
            except (TypeError, ValueError):
                raise ValueError(f"Định mức của “{name}” không phải số.")
            if name in self.item_mem:
                if not overwrite:
                    res["bo_qua"] += 1
                    continue
                res["ghi_de"] += 1
            else:
                res["them"] += 1
            self.item_mem[name] = new
        self.save_catalog()
        return res

    def export_learned(self, key):
        """Dữ liệu học của một khách đã học/thêm mới (hồ sơ + danh mục hàng + định mức + file mẫu chứng từ) để máy khác nạp bằng "Nạp dữ liệu học"."""
        import base64
        if key in BUILTIN_CUSTOMERS or key not in self.custom_profiles:
            raise ValueError("Chỉ xuất được dữ liệu học của khách đã học / thêm mới (khách có sẵn đã nằm sẵn trong phần mềm).")
        items = [dict(x) for x in self.custom_items.get(key, [])]
        mau = {}
        folder = os.path.join(TEMPLATE_DIR or os.path.join(self.base_dir, "MAU_CHUNG_TU"), key)
        for doc in ("pkl", "pack", "pgh", "dccn", "dntt", "bbgh"):
            path = os.path.join(folder, doc + ".xlsx")
            if os.path.isfile(path):
                with open(path, "rb") as f:
                    mau[doc] = base64.b64encode(f.read()).decode("ascii")
        mem = {it["name"]: self.item_mem[it["name"]] for it in items if it.get("name") in self.item_mem}
        return {"version": "hongthien-hoc-v1", "khach_moi": {"key": key, "profile": dict(self.custom_profiles[key]), "items": items, "mau": mau}, "item_mem": mem}

    def save_templates(self, key, mau, overwrite=False):
        """Lưu file mẫu chứng từ của khách (base64 trong file dữ liệu học) vào MAU_CHUNG_TU/<khách>/<doc>.xlsx."""
        import base64
        folder = os.path.join(TEMPLATE_DIR or os.path.join(self.base_dir, "MAU_CHUNG_TU"), key)
        n = 0
        for doc, b64 in (mau or {}).items():
            if doc not in ("pkl", "pack", "pgh", "dccn", "dntt", "bbgh"):
                continue
            path = os.path.join(folder, doc + ".xlsx")
            if os.path.exists(path) and not overwrite:
                continue
            os.makedirs(folder, exist_ok=True)
            with open(path, "wb") as f:
                f.write(base64.b64decode(b64))
            n += 1
        return n

    # ---- DATA TỔNG: danh mục sản phẩm dùng chung (tên, kg/chiếc, SL/kiện) nằm trong thư mục HAI_QUAN ----------------
    # Một file DATA_TONG.json (trong thư mục dữ liệu dùng chung) cho mọi máy. Nguồn: file ERP (kg), invoice cũ (kg + SL/kiện), người dùng xác nhận khi xuất.
    # Ưu tiên khi trùng: tay (đã xác nhận) > invoice cũ > ERP.
    DT_RANK = {"tay": 3, "invoice": 2, "erp": 1, "": 0}

    def dt_path(self):
        """DATA_TONG.json nằm trong thư mục HAI_QUAN, ngang hàng với thư mục tên khách; chỉ đọc và ghi ở đây."""
        return os.path.join(self.customs_root(), DT_FILE)

    def dt_load(self):
        data = self._read_json(self.dt_path(), {})
        self.data_tong = list(data.get("items") or []) if isinstance(data, dict) else []
        self._dt_cache, self._dt_idx, self._dt_cust = {}, None, {}

    def dt_save(self):
        try:
            os.makedirs(os.path.dirname(self.dt_path()), exist_ok=True)
            with self._lock():
                if self._sig(self.dt_path()) != self._sigs.get(self.dt_path()):  # máy khác vừa ghi: gộp
                    disk = (self._read_json(self.dt_path(), {}) or {}).get("items") or []
                    mine = {self._dt_key(x): x for x in self.data_tong}
                    for d in disk:
                        k = self._dt_key(d)
                        if k not in mine:
                            mine[k] = d
                        elif str(d.get("ts") or "") > str(mine[k].get("ts") or ""):
                            mine[k] = d
                    self.data_tong = list(mine.values())
                self._write_json(self.dt_path(), {"version": 1, "cap_nhat": datetime.datetime.now().strftime("%d/%m/%Y %H:%M"), "items": self.data_tong}, compact=True)
                self._sigs[self.dt_path()] = self._sig(self.dt_path())
            self._dt_cache, self._dt_idx = {}, None
        except Exception as e:
            print("Warning saving data tong:", e)

    def _dt_index(self):
        if self._dt_idx is None:
            self._dt_idx = {self._dt_key(x): x for x in self.data_tong}
        return self._dt_idx

    @staticmethod
    def _dt_key(it):
        return f"{clean_str(it.get('khach'))}|{clean_str(it.get('ten'))}"

    @staticmethod
    def _dims_key(name):
        try:
            dims = _name_dims(name)[0]
            return tuple(int(round(float(d))) for d in dims) if len(dims) >= 3 else None
        except Exception:
            return None

    @staticmethod
    def _khach_match(prof, khach):
        k = clean_str(khach)
        if not k:
            return False
        names = {clean_str(prof.get("label")), clean_str(prof.get("key"))}
        full = clean_str(prof.get("name"))
        return k in names or (len(k) >= 3 and k in full) or (bool(full) and full in k)

    def dt_items_for(self, cust_key):
        """Mục data tổng của một khách (đã nạp vào bộ nhớ đệm, xóa khi dữ liệu đổi)."""
        if cust_key not in self._dt_cache:
            prof = PROFILES.get(cust_key) or {}
            self._dt_cache[cust_key] = [x for x in self.data_tong if self._khach_match(prof, x.get("khach")) or self._khach_match(prof, x.get("khach_day_du"))]
        return self._dt_cache[cust_key]

    def dt_lookup(self, cust_key, name="", code=""):
        cands = self.dt_items_for(cust_key)
        code = str(code or "").strip()
        if code:
            hit = [x for x in cands if code and code in (str(x.get("ma_hang") or "").strip(), str(x.get("ma_erp") or "").strip(), str(x.get("ma_kh") or "").strip())]
            if hit:
                return max(hit, key=lambda x: (bool(x.get("kg")) + bool(x.get("kien")), self.DT_RANK.get(x.get("kg_nguon", ""), 0)))
        nk = clean_str(name)
        hit = [x for x in cands if nk and nk in (clean_str(x.get("ten")), clean_str(x.get("ten_kh")))]
        if not hit:
            dk = self._dims_key(name)
            hit = [x for x in cands if dk and self._dims_key(x.get("ten")) == dk]
            if len({(x.get("kg"), x.get("kien")) for x in hit}) > 1:
                hit = []  # nhiều sản phẩm cùng quy cách mà khác số liệu: không đoán
        return max(hit, key=lambda x: (bool(x.get("kg")) + bool(x.get("kien")), self.DT_RANK.get(x.get("kg_nguon", ""), 0))) if hit else None

    def _dt_upsert(self, khach, ten, ma_hang="", ma_erp="", kg=0.0, kg_nguon="", kien=0, kien_nguon="", hs="", exact=False):
        """Thêm/sửa một sản phẩm. Số liệu nguồn yếu hơn không đè nguồn mạnh hơn. Trả True nếu có thay đổi."""
        cust = self._dt_cust.get(khach)
        if khach not in self._dt_cust:
            cust = self._dt_cust[khach] = next((k for k, p in PROFILES.items() if self._khach_match(p, khach)), None)
        key = f"{clean_str(khach)}|{clean_str(ten)}"
        it = self._dt_index().get(key) or (self.dt_lookup(cust, ten, ma_hang or ma_erp) if cust and not exact else None)
        now = datetime.datetime.now()
        user = self.user_name()
        changed = False
        if it is None:
            it = {"khach": khach, "ten": ten, "ma_hang": ma_hang, "ma_erp": ma_erp, "kg": 0, "kg_nguon": "", "kien": 0, "kien_nguon": "", "hs": hs}
            self.data_tong.append(it)
            self._dt_idx[key] = it
            self._dt_cache.pop(cust, None)
            changed = True
        for field, val in (("ma_hang", ma_hang), ("ma_erp", ma_erp), ("hs", hs)):
            if val and it.get(field) != val and not it.get(field):
                it[field] = val
                changed = True
        if kg and (self.DT_RANK.get(kg_nguon, 0) >= self.DT_RANK.get(it.get("kg_nguon", ""), 0)) and abs(float(it.get("kg") or 0) - float(kg)) > 1e-9:
            it["kg"], it["kg_nguon"] = round(float(kg), 6), kg_nguon
            changed = True
        elif kg and not it.get("kg"):
            it["kg"], it["kg_nguon"] = round(float(kg), 6), kg_nguon
            changed = True
        if kien and (self.DT_RANK.get(kien_nguon, 0) >= self.DT_RANK.get(it.get("kien_nguon", ""), 0)) and float(it.get("kien") or 0) != float(kien):
            it["kien"], it["kien_nguon"] = kien, kien_nguon
            changed = True
        if ten and kg_nguon in ("invoice", "tay") and it.get("ten") != ten:
            it.setdefault("ten_erp", it.get("ten"))
            it["ten"] = ten  # tên dùng trên chứng từ
            changed = True
        if changed:
            it["ts"] = now.strftime("%Y-%m-%d %H:%M:%S")
            it["cap_nhat"] = now.strftime("%d/%m/%Y %H:%M")
            it["may"] = user
        return changed

    def dt_import_erp(self, path):
        """Nạp file ERP (Excel): Tên tắt khách hàng | Mã cũ | Mã số | Tên (vn) | Cân nặng (g). Trả {"them", "cap_nhat", "bo_qua"}."""
        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
        res = {"them": 0, "cap_nhat": 0, "bo_qua": 0}
        for ws in wb.worksheets:
            cols = None
            for row in ws.iter_rows(values_only=True):
                if cols is None:
                    heads = [strip_accents_upper(v or "") for v in row]
                    if any(h.startswith("TEN TAT KHACH") for h in heads) and any(h.startswith("CAN NANG") for h in heads):
                        cols = {"khach": next(i for i, h in enumerate(heads) if h.startswith("TEN TAT KHACH")),
                                "ma_cu": next((i for i, h in enumerate(heads) if h.startswith("MA CU")), None),
                                "ma": next((i for i, h in enumerate(heads) if h == "MA SO"), None),
                                "ten": next((i for i, h in enumerate(heads) if h.startswith("TEN (VN)") or h.startswith("TEN VN")), None),
                                "g": next(i for i, h in enumerate(heads) if h.startswith("CAN NANG"))}
                    continue
                get = lambda k: (row[cols[k]] if cols.get(k) is not None and cols[k] < len(row) else None)
                khach, ten, g = str(get("khach") or "").strip(), str(get("ten") or "").strip(), get("g")
                if not khach or khach.lower() == "none" or not ten or not isinstance(g, (int, float)) or g <= 0:
                    res["bo_qua"] += 1
                    continue
                before = len(self.data_tong)
                ch = self._dt_upsert(khach, ten, ma_hang=str(get("ma_cu") or "").strip(), ma_erp=str(get("ma") or "").strip(), kg=g / 1000.0, kg_nguon="erp", exact=True)
                if len(self.data_tong) > before:
                    res["them"] += 1
                elif ch:
                    res["cap_nhat"] += 1
        wb.close()
        self._dt_cache = {}
        self.dt_save()
        return res

    def dt_import_mapping(self, path):
        """Nạp file 'mã sản phẩm theo khách hàng': Mã sản phẩm gốc | Tên gốc | Mã KH | Tên khách hàng | Mã SP theo KH | Tên SP theo KH.
        Gắn mã và tên sản phẩm theo khách vào sản phẩm ERP cùng mã (kg đã có từ file ERP). Trả {"them", "cap_nhat", "bo_qua"}."""
        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
        res = {"them": 0, "cap_nhat": 0, "bo_qua": 0}
        by_erp = {}
        for x in self.data_tong:
            if x.get("ma_erp"):
                by_erp.setdefault(x["ma_erp"], []).append(x)
        for ws in wb.worksheets:
            cols = None
            for row in ws.iter_rows(values_only=True):
                if cols is None:
                    heads = [strip_accents_upper(v or "") for v in row]
                    if any(h.startswith("MA SAN PHAM GOC") for h in heads) and any("THEO KH" in h for h in heads):
                        cols = {"erp": next(i for i, h in enumerate(heads) if h.startswith("MA SAN PHAM GOC")),
                                "ten_goc": next((i for i, h in enumerate(heads) if h.startswith("TEN SAN PHAM GOC")), None),
                                "khach": next(i for i, h in enumerate(heads) if h.startswith("TEN KHACH HANG")),
                                "ma_kh": next((i for i, h in enumerate(heads) if h.startswith("MA SAN PHAM THEO")), None),
                                "ten_kh": next(i for i, h in enumerate(heads) if h.startswith("TEN SAN PHAM THEO"))}
                    continue
                get = lambda k: (row[cols[k]] if cols.get(k) is not None and cols[k] < len(row) else None)
                erp, khach, ten_kh = str(get("erp") or "").strip(), str(get("khach") or "").strip(), str(get("ten_kh") or "").strip()
                if not erp or not khach or not ten_kh:
                    res["bo_qua"] += 1
                    continue
                m = re.search(r"(?<![A-Za-z0-9])(\d[A-Z0-9]{9,})(?![A-Za-z0-9])", ten_kh)
                ma_kh = m.group(1) if m else ""
                ten_sach = re.sub(r"\s+", " ", re.sub(r"\(?\s*" + re.escape(ma_kh) + r"\s*\)?", " ", ten_kh)).strip() if ma_kh else ten_kh
                targets = by_erp.get(erp) or []
                created = False
                if not targets:
                    it = {"khach": khach, "ten": str(get("ten_goc") or ten_kh).strip(), "ma_hang": "", "ma_erp": erp, "kg": 0, "kg_nguon": "", "kien": 0, "kien_nguon": "", "hs": ""}
                    self.data_tong.append(it)
                    by_erp[erp] = targets = [it]
                    created = True
                changed = False
                for it in targets:
                    for k, v in (("ma_kh", ma_kh), ("ten_kh", ten_sach), ("khach_day_du", khach)):
                        if v and it.get(k) != v:
                            it[k], changed = v, True
                    if changed:
                        it["ts"] = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                res["them" if created else "cap_nhat"] += 1 if (created or changed) else 0
        wb.close()
        self._dt_cache, self._dt_idx = {}, None
        self.dt_save()
        return res

    def dt_import_invoices(self, paths, cust_key):
        """Học kg/chiếc và SL/kiện từ invoice cũ của khách `cust_key` (SL/kiện = SL / số kiện ghi trên invoice)."""
        prof = PROFILES[cust_key]
        khach = prof.get("label") or cust_key
        res = {"them": 0, "cap_nhat": 0, "file": 0, "loi": []}
        for p in paths:
            try:
                d = learn_from_invoice_excel(p, ignore_norms=True)
            except Exception as e:
                res["loi"].append(f"{os.path.basename(p)}: {e}")
                continue
            res["file"] += 1
            merged = {}
            for it in d["items"]:  # mỗi sản phẩm: lấy giá trị đầu tiên có số liệu (sheet mới nhất đứng trước; sheet thiếu kg/kiện bị bù từ sheet khác)
                m = merged.setdefault(clean_str(it.get("name")), {"name": it["name"]})
                for f in ("code", "kg", "div", "hs"):
                    if it.get(f) and not m.get(f):
                        m[f] = it[f]
            for m in merged.values():
                before = len(self.data_tong)
                div = m.get("div") or 0
                ch = self._dt_upsert(khach, m["name"], ma_hang=str(m.get("code") or "").strip(), kg=m.get("kg") or 0, kg_nguon="invoice",
                                     kien=int(round(div)) if div else 0, kien_nguon="invoice", hs=str(m.get("hs") or ""))
                if len(self.data_tong) > before:
                    res["them"] += 1
                elif ch:
                    res["cap_nhat"] += 1
        self._dt_cache = {}
        self.dt_save()
        return res

    def dt_learn_items(self, cust_key, items):
        """Mỗi lần xuất chứng từ: nhớ kg/chiếc và SL/kiện người dùng đã xác nhận (nguồn 'tay') vào data tổng dùng chung."""
        prof = PROFILES.get(cust_key)
        if not prof:
            return 0
        khach = prof.get("label") or cust_key
        n = 0
        for it in items:
            kg, div = float(it.get("kg") or 0), float(it.get("div") or 0)
            if kg > 0 or div > 0:
                if self._dt_upsert(khach, str(it.get("ten_sp") or ""), ma_hang=str(it.get("ma_sp") or "").strip(), kg=kg, kg_nguon="tay",
                                   kien=int(round(div)) if div else 0, kien_nguon="tay", hs=str(it.get("hs") or "")):
                    n += 1
        if n:
            self._dt_cache = {}
            self.dt_save()
        return n

    def dt_fill_lines(self, cust_key, lines):
        """Dòng hàng còn thiếu kg/chiếc hoặc SL/kiện thì lấy từ data tổng rồi tính lại kiện, tịnh, cả bì. Trả số dòng được điền."""
        n = 0
        for ln in lines:
            if float(ln.get("kg") or 0) > 0 and float(ln.get("div") or 0) > 0:
                continue
            it = self.dt_lookup(cust_key, ln.get("ten_sp"), ln.get("ma_sp"))
            if not it:
                continue
            changed = False
            if not float(ln.get("kg") or 0) and it.get("kg"):
                ln["kg"], changed = float(it["kg"]), True
            if not float(ln.get("div") or 0) and it.get("kien"):
                ln["div"], changed = float(it["kien"]), True
            if changed:
                qty, kg, div, tare = float(ln.get("qty") or 0), float(ln.get("kg") or 0), float(ln.get("div") or 0), float(ln.get("tare") or 0)
                ln["kien"] = math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0
                ln["net"] = round_half_up(qty * kg, 2) if kg > 0 else 0.0
                ln["gross"] = round_half_up(ln["net"] + tare, 2) if ln["net"] > 0 else 0.0
                n += 1
        return n

    def update_customer(self, key, fields):
        """Sửa thông tin khách (tên, MST, địa chỉ…). Khách có sẵn: lưu phần sửa; khách đã học: sửa trong hồ sơ khách."""
        if key not in PROFILES:
            raise ValueError("Không tìm thấy khách hàng này.")
        names = dict(CUSTOMER_FIELDS)
        clean = {k: str(v).strip() for k, v in fields.items() if k in names}
        if clean.get("xe"):  # chỉ lưu biển số; chữ "Ô tô tải:" do chứng từ tự thêm
            clean["xe"] = re.sub(r"^\s*[ÔôOo]\s*tô\s*tải\s*:?\s*", "", clean["xe"], flags=re.I).strip()
        if "name" in clean and not clean["name"]:
            raise ValueError("Tên công ty của khách không được để trống.")
        if clean.get("mst") and not re.fullmatch(r"[0-9\-]{10,14}", clean["mst"]):
            raise ValueError("Mã số thuế gồm 10 đến 14 chữ số (có thể kèm dấu -).")
        if key in BUILTIN_CUSTOMERS:
            self.profile_overrides.setdefault(key, {}).update(clean)
            apply_profile_overrides(self.profile_overrides)
        else:
            prof = self.custom_profiles.setdefault(key, {})
            prof.update(clean)
            PROFILES[key] = build_custom_profile(key, prof)
            apply_company_exporter()
        self.save_catalog()
        return PROFILES[key]

    def add_customer(self, fields):
        """Thêm khách mới chỉ với thông tin hành chính (chưa có danh mục hàng). Trả mã khách."""
        name = str(fields.get("name", "")).strip()
        if not name:
            raise ValueError("Hãy nhập tên công ty của khách.")
        if fields.get("mst") and not re.fullmatch(r"[0-9\-]{10,14}", str(fields["mst"]).strip()):
            raise ValueError("Mã số thuế gồm 10 đến 14 chữ số (có thể kèm dấu -).")
        key = customer_key_from_name(name, taken=set(PROFILES))
        prof = {k: str(v).strip() for k, v in fields.items() if k in dict(CUSTOMER_FIELDS) and str(v).strip()}
        prof.setdefault("label", name.split()[-1].capitalize() if name.split() else key.capitalize())
        self.save_learned_customer(key, prof, [])
        apply_company_exporter()
        return key

    # ---- dùng chung một thư mục dữ liệu giữa nhiều máy (không cần mạng LAN, không máy chủ) -------------------------
    # Mọi máy trỏ vào cùng một thư mục (ổ chung, OneDrive, Google Drive...). Ghi file: khóa ngắn + gộp với bản mới nhất
    # trên đĩa + ghi qua file tạm, nên hai máy lưu gần nhau không đè mất dữ liệu của nhau.
    LOCK_WAIT, LOCK_STALE = 8.0, 30.0

    def _sig(self, path):
        try:
            st = os.stat(path)
            return (st.st_mtime_ns, st.st_size)
        except OSError:
            return None

    def _note_sigs(self):
        self._sigs = {p: self._sig(p) for p in (self.catalog_file, self.records_file, self.dt_path())}

    def changed_on_disk(self):
        """True nếu máy khác đã ghi file dữ liệu kể từ lần đọc/ghi gần nhất của máy này."""
        return any(self._sig(p) != self._sigs.get(p) for p in (self.catalog_file, self.records_file, self.dt_path()))

    def sync(self):
        """Đọc lại dữ liệu nếu máy khác vừa thay đổi. Trả True nếu có đọc lại."""
        if not self.changed_on_disk():
            return False
        self.load_all()
        return True

    @contextlib.contextmanager
    def _lock(self):
        path = os.path.join(self.base_dir, ".khoa_ghi")
        t0, held = time.time(), False
        while True:
            try:
                os.close(os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY))
                held = True
                break
            except FileExistsError:
                try:
                    if time.time() - os.path.getmtime(path) > self.LOCK_STALE:  # máy trước tắt đột ngột: bỏ khóa cũ
                        os.remove(path)
                        continue
                except OSError:
                    pass
                if time.time() - t0 > self.LOCK_WAIT:
                    break  # chờ quá lâu thì vẫn ghi (khóa chỉ để giảm va chạm, không để chặn người dùng)
                time.sleep(0.1)
            except OSError:
                break
        try:
            yield
        finally:
            if held:
                try:
                    os.remove(path)
                except OSError:
                    pass

    def _write_json(self, path, obj, compact=False):
        tmp = f"{path}.{os.getpid()}.tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            if compact:  # file lớn (data tổng): bỏ thụt dòng cho nhỏ và ghi nhanh
                json.dump(obj, f, ensure_ascii=False, separators=(",", ":"))
            else:
                json.dump(obj, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)

    def _read_json(self, path, default):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return default

    def save_catalog(self):
        try:
            with self._lock():
                disk = self._read_json(self.catalog_file, {}) if self.changed_on_disk() else {}
                if disk:  # gộp phần máy khác vừa thêm; mục trùng thì bản của máy này thắng
                    for k in ("item_mem", "custom_profiles", "profile_overrides", "weights_db"):
                        merged = dict(disk.get(k) or {})
                        merged.update(getattr(self, k, {}) or {})
                        setattr(self, k, merged)
                    items = {k: list(v) for k, v in (disk.get("custom_items") or {}).items()}
                    for k, lst in self.custom_items.items():
                        have = items.setdefault(k, [])
                        for row in lst:
                            ix = next((n for n, x in enumerate(have) if x.get("name") == row.get("name")), -1)
                            if ix >= 0:
                                have[ix] = row
                            else:
                                have.append(row)
                    self.custom_items = items
                if disk:
                    seen = {json.dumps(x, sort_keys=True) for x in self.read_fixes}
                    self.read_fixes = [x for x in (disk.get("read_fixes") or []) if json.dumps(x, sort_keys=True) not in seen] + self.read_fixes
                self._write_json(self.catalog_file, {
                    "read_fixes": self.read_fixes[-300:],
                    "company": HT_NAME,
                    "address": ADDR_HT,
                    "tax_code": MST_HT,
                    "company_info": self.company,
                    "profile_overrides": self.profile_overrides,
                    "weights_db": self.weights_db,
                    "erp_catalog": self.erp_catalog,
                    "kodi_items": self.kodi_items,
                    "tesa_items": self.tesa_items,
                    "item_mem": self.item_mem,
                    "custom_profiles": self.custom_profiles,
                    "custom_items": self.custom_items,
                })
                self._sigs[self.catalog_file] = self._sig(self.catalog_file)
        except Exception as e:
            print("Warning saving catalog:", e)

    def save_records(self):
        try:
            with self._lock():
                if self._sig(self.records_file) != self._sigs.get(self.records_file):
                    disk = self._read_json(self.records_file, [])
                    local_ids = {r.get("id") for r in self.records}
                    for r in disk:  # hồ sơ máy khác vừa thêm/sửa
                        rid = r.get("id")
                        if rid in getattr(self, "_loaded_ids", set()):
                            ix = next((n for n, x in enumerate(self.records) if x.get("id") == rid), -1)
                            if ix >= 0 and str(r.get("updatedAt") or "") > str(self.records[ix].get("updatedAt") or ""):
                                self.records[ix] = r  # máy kia sửa mới hơn
                        elif rid not in local_ids:
                            self.records.append(r)
                self._write_json(self.records_file, self.records)
                self._loaded_ids = {r.get("id") for r in self.records}
                self._sigs[self.records_file] = self._sig(self.records_file)
        except Exception as e:
            print("Warning saving records JSON:", e)
        try:
            tmp_db = os.path.join(tempfile.gettempdir(), "ht_sync_temp.db")
            if os.path.exists(self.sqlite_file):
                shutil.copy2(self.sqlite_file, tmp_db)
            conn = sqlite3.connect(tmp_db)
            cur = conn.cursor()
            cur.execute("""
                CREATE TABLE IF NOT EXISTS ho_so_hai_quan (
                    ma_ho_so TEXT PRIMARY KEY, phan_vung TEXT, khach_hang TEXT, ngay_chung_tu TEXT,
                    so_po TEXT, ngay_po TEXT, dot_giao TEXT, so_pxk TEXT, so_hoa_don TEXT,
                    so_to_khai TEXT, luong_to_khai TEXT, bien_so_xe TEXT, lai_xe TEXT, ma_ldd TEXT,
                    tong_so_luong REAL, tong_thanh_tien REAL, tong_kl_tinh REAL, tong_kl_ca_bi REAL,
                    tong_so_kien REAL, thu_muc_luu_tru TEXT, cap_nhat_luc TEXT
                )
            """)
            cur.execute("DELETE FROM ho_so_hai_quan")
            for r in self.records:
                cur.execute(
                    "INSERT OR REPLACE INTO ho_so_hai_quan VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        r.get("id", ""), r.get("zone", "WORKING"), r.get("customer", ""),
                        r.get("docDate", ""), r.get("poNumber", ""), r.get("poDate", ""),
                        r.get("scheduleKey", ""), r.get("pxkNo", ""), r.get("hdNo", ""),
                        r.get("tkNo", ""), r.get("luong", "Xanh"), r.get("xeNo", ""),
                        r.get("driver", ""), r.get("lddSeq", "01"), r.get("totalQty", 0),
                        r.get("totalAmount", 0), r.get("totalNet", 0), r.get("totalGross", 0),
                        r.get("totalKien", 0), self.get_record_folder_path(r), r.get("updatedAt", ""),
                    ),
                )
            conn.commit()
            conn.close()
            shutil.copy2(tmp_db, self.sqlite_file)
        except Exception:
            pass

    # Thư mục tờ khai: bên trong DO_PHAN_MEM_TAO là file do phần mềm tạo (Excel) + PO gốc; bên ngoài là file khác
    # (scan, PDF Bkav, file hải quan). Tên file dùng để biết bộ hồ sơ đã có gì.
    MADE_PREFIXES = (("invoice_", "Invoice (Excel)"), ("DongGoi_", "Đóng gói (Excel)"), ("Hoa_Don_VAT", "Hóa đơn Bkav (Excel)"), ("PXK_", "PXK Bkav (Excel)"),
                     ("ToKhai_B11", "Dữ liệu tờ khai B11"), ("PhieuGiaoHang", "Phiếu giao hàng"), ("DoiChieuCongNo", "Đối chiếu công nợ"),
                     ("DNTT", "Đề nghị thanh toán"), ("dsh_", "Danh sách hàng ECUS (Excel)"), ("KiemTraCheo", "Kiểm tra chéo"),
                     ("Bo_Ho_So_Xuat_Hang", "Bộ hồ sơ"), ("00_HO_SO_", "Hồ sơ lưu"), ("PLX_", "PLX (Excel)"), ("SO_", "Đơn đặt hàng"), ("PO_goc_", "PO gốc"), ("BienBanBanGiao", "Biên bản bàn giao"), ("dccn", "Đối chiếu công nợ"))
    MODE_TO_MADE = {"PKL": "Invoice (Excel)", "PACK": "Đóng gói (Excel)", "VAT": "Hóa đơn Bkav (Excel)", "PXK": "PXK Bkav (Excel)", "B11": "Dữ liệu tờ khai B11",
                    "PGH": "Phiếu giao hàng", "DCCN": "Đối chiếu công nợ", "DNTT": "Đề nghị thanh toán", "PLX": "PLX (Excel)", "SO": "Đơn đặt hàng",
                    "BBGH": "Biên bản bàn giao", "DSH": "Danh sách hàng ECUS (Excel)"}
    PREPARED_PREFIXES = MADE_PREFIXES  # tên cũ

    @classmethod
    def _classify_outside(cls, name):
        """Nhận biết file bên ngoài (không do phần mềm tạo) chỉ bằng tên: trả nhãn hoặc ''."""
        n = name.lower()
        base, ext = os.path.splitext(n)
        pdfish = ext in (".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff")
        if pdfish and (re.search(r"c\d{2}n[a-z]{2}", base) or re.match(r"pxk\s*\d", base)):
            return "PXK Bkav (PDF)"
        if pdfish and (re.search(r"c\d{2}t[a-z]{2}", base) or re.match(r"h[đd]\s*\d", base)):
            return "Hóa đơn Bkav (PDF)"
        if base.startswith("dsh"):
            return "DSH hải quan"
        if re.search(r"(?<!\d)\d{12}(?!\d)", base) or "tokhai" in base.replace("_", "").replace(" ", ""):
            return "Tờ khai"
        if pdfish and "plx" in base:
            return "PLX (scan)"
        if pdfish and re.match(r"(iv|inv|invoice)", base):
            return "Invoice (scan)"
        if pdfish and re.match(r"po", base):
            return "PO (scan)"
        return ""

    @classmethod
    def folder_checklist(cls, modes):
        """Bộ hồ sơ đầy đủ của một khách theo các chứng từ `modes` của khách đó: (phần phần mềm tạo, phần bên ngoài)."""
        made = ["PO gốc"] + [cls.MODE_TO_MADE[m] for m in modes if m in cls.MODE_TO_MADE and m != "DSH"]
        out = ["PO (scan)"]
        for m, lbl in (("PKL", "Invoice (scan)"), ("PLX", "PLX (scan)"), ("VAT", "Hóa đơn Bkav (PDF)"), ("PXK", "PXK Bkav (PDF)")):
            if m in modes:
                out.append(lbl)
        return made, out + ["DSH hải quan", "Tờ khai"]

    @classmethod
    def folder_activity(cls, path, modes=None):
        """Đọc thư mục tờ khai, biết đã làm gì chỉ bằng tên file.
        prepared = file do phần mềm tạo (trong DO_PHAN_MEM_TAO hoặc cùng thư mục kiểu cũ); other = file bên ngoài;
        have = nhãn các chứng từ đã có; missing = còn thiếu theo bộ của khách (nếu biết `modes`); tk = số tờ khai 12 số trong tên file."""
        def names_in(d):
            try:
                return sorted(n for n in os.listdir(d) if not n.startswith((".", "~$")) and os.path.isfile(os.path.join(d, n)))
            except OSError:
                return []
        prepared, other, have, tk = [], [], set(), ""
        for n in names_in(os.path.join(path, GENERATED_DIR)):
            hit = next((lbl for pre, lbl in cls.MADE_PREFIXES if n.lower().startswith(pre.lower())), "Khác")
            have.add(hit)
            if hit not in prepared:
                prepared.append(hit)
        for n in names_in(path):
            hit = next((lbl for pre, lbl in cls.MADE_PREFIXES if n.lower().startswith(pre.lower())), "")
            if hit:  # hồ sơ kiểu cũ: file do phần mềm tạo nằm cùng thư mục
                have.add(hit)
                if hit not in prepared:
                    prepared.append(hit)
                continue
            other.append(n)
            lbl = cls._classify_outside(n)
            if lbl:
                have.add(lbl)
            m = re.search(r"(?<!\d)(\d{12})(?!\d)", n)
            if m and not tk:
                tk = m.group(1)
        missing = []
        if modes:
            made, out = cls.folder_checklist(modes)
            missing = [x for x in made + out if x not in have]
        if not prepared and not other:
            status = "Thư mục trống"
        else:
            head = f"Đã khai · số tờ khai {tk} · " if tk else ""
            status = head + ("Đủ bộ hồ sơ" if modes and not missing else (f"Thiếu: {', '.join(missing[:4])}{'…' if len(missing) > 4 else ''}" if missing else f"Đã chuẩn bị {len(prepared)} chứng từ"))
        return {"prepared": prepared, "other": other, "have": sorted(have), "missing": missing, "tk": tk, "status": status}

    def _modes_for_folder(self, cust_label, rec):
        """Các chứng từ thuộc bộ của khách (theo hồ sơ nếu có, không thì theo tên thư mục khách); None nếu không nhận ra khách."""
        key = (rec or {}).get("customer")
        if not key:
            key = next((k for k, p in PROFILES.items() if self._khach_match(p, cust_label)), None)
        return lot_bundle_modes({"customer": key}) if key in PROFILES else None

    def declaration_folders(self):
        """Các thư mục tờ khai đang có trong HAI_QUAN (quét thật trên ổ đĩa/OneDrive) ghép với thông tin hồ sơ nếu có.
        Mỗi mục: {customer, label, day, path, record (hoặc None), files}. Mới nhất trước. Thư mục bắt đầu bằng _ bị bỏ qua."""
        root = self.customs_root()
        by_path = {}
        for r in self.records:
            try:
                by_path[os.path.normcase(os.path.normpath(self.get_record_folder_path(r)))] = r
            except Exception:
                pass
        out, seen = [], set()
        skip = {CUSTOMS_ROOT, "MAU_CHUNG_TU", GENERATED_DIR, "_KIEM_TRA"}
        roots = [root]
        nested = os.path.join(root, CUSTOMS_ROOT)  # thư mục HAI_QUAN lồng bên trong do bản cũ tạo ra
        if os.path.isdir(nested):
            roots.append(nested)
        def has_files(d):
            try:
                return any(not n.startswith((".", "~$")) and os.path.isfile(os.path.join(d, n)) for n in os.listdir(d))
            except OSError:
                return False
        def rec_for(path):
            norm = os.path.normcase(path)
            for r in self.records:
                for key in (r.get("tkNo"), str(r.get("poNumber") or "").split()[0].split("..")[0] if r.get("poNumber") else ""):
                    if key and len(str(key)) >= 5 and str(key).lower() in norm:
                        return r
            return None
        def add(cust, path, day):
            key = os.path.normcase(os.path.normpath(path))
            if key in seen or any(key.startswith(k + os.sep) for k in seen if has_files(k)):
                return
            seen.add(key)
            rec = by_path.get(key) or rec_for(path)
            files = [f for f in os.listdir(path) if not f.startswith(".")]
            out.append({"customer": cust, "label": cust, "day": day, "path": path, "record": rec, "files": len(files), **self.folder_activity(path, self._modes_for_folder(cust, rec))})
        for rt in roots:
            try:
                custs = sorted(d for d in os.listdir(rt) if not d.startswith("_") and d.upper() not in skip and os.path.isdir(os.path.join(rt, d)))
            except OSError:
                custs = []
            for cust in custs:
                cdir = os.path.join(rt, cust)
                for dirpath, dirs, _files in os.walk(cdir):
                    dirs[:] = sorted(d for d in dirs if not d.startswith((".", "_")) and d != GENERATED_DIR)
                    if dirpath != cdir and (has_files(dirpath) or (not dirs and re.match(r"\d{4}-\d{2}-\d{2}", os.path.basename(dirpath)))):
                        add(cust, dirpath, os.path.basename(dirpath))
                        dirs[:] = []  # thư mục có file là thư mục tờ khai, không đi sâu thêm
                    elif dirpath == cdir and has_files(cdir) and not dirs:
                        add(cust, cdir, os.path.basename(cdir))
                    if dirpath.count(os.sep) - cdir.count(os.sep) >= 4:
                        dirs[:] = []
        for key, r in by_path.items():  # hồ sơ đã lưu có thư mục nhưng chưa có file nào
            if key not in seen and os.path.isdir(key):
                out.append({"customer": r.get("customer", ""), "label": PROFILES.get(r.get("customer", ""), {}).get("label", r.get("customer", "")),
                            "day": r.get("docDate", ""), "path": key, "record": r, "files": 0,
                            "prepared": [], "other": [], "tk": "", "status": "Thư mục trống"})
        for o in out:
            r = o["record"]
            if r:
                o["label"] = PROFILES.get(r.get("customer", ""), {}).get("label", o["label"])
        out.sort(key=lambda o: (str((o["record"] or {}).get("docDate") or o["day"])[:10], o["path"]), reverse=True)
        return out

    # ---- nhớ cách đọc PO: quy tắc vị trí số + nhật ký sửa lỗi ---------------------------------
    def read_rules(self, cust_key):
        """Quy tắc đọc đã học của khách: {'qty': -3, 'price': -2, 'n': 5} = SL là số thứ 3 tính từ cuối dòng, đơn giá thứ 2; áp khi dòng PO có đúng n số."""
        return dict((self.custom_profiles.get(cust_key) or {}).get("readRules") or {})

    def learn_read_rule(self, cust_key, rule, fixes):
        """Lưu quy tắc (nếu có) vào hồ sơ khách và ghi nhật ký các chỗ máy đọc sai. `fixes`: [{field, read, correct, how, line, po, file}]."""
        if rule and cust_key in self.custom_profiles:
            self.custom_profiles[cust_key]["readRules"] = rule
            if cust_key in PROFILES:
                PROFILES[cust_key]["readRules"] = rule
        stamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
        for f in fixes:
            self.read_fixes.append({"time": stamp, "customer": cust_key, "machine": self.user_name() if hasattr(self, "user_name") else "", **f})
        self.save_catalog()

    def read_fix_log(self, cust_key=None, limit=20):
        rows = [x for x in self.read_fixes if not cust_key or x.get("customer") == cust_key]
        return rows[-limit:][::-1]

    def pxk_numbers(self):
        """Mọi số phiếu xuất kho đã dùng: từ hồ sơ đã lưu, từ tên file 'PXK 247.pdf' / tờ khai '<số PXK>_<số tờ khai>' trong thư mục hồ sơ.
        Trả [(số nguyên, chuỗi gốc)]. Số phiếu xuất kho là dãy số chung của công ty (không riêng từng khách)."""
        found = []
        demo = {"HS-20261030-TESA-01", "HS-20261028-KODI-01", "HS-20261030-SHIRAI-01"}  # hồ sơ mẫu có sẵn của phần mềm: số PXK của chúng không tính
        for r in self.records:
            if r.get("id") in demo:
                continue
            m = re.fullmatch(r"\s*0*(\d{1,9})\s*", str(r.get("pxkNo") or ""))
            if m:
                found.append((int(m.group(1)), str(r["pxkNo"]).strip()))
        try:
            for o in self.declaration_folders():
                for n in os.listdir(o["path"]):
                    m = re.match(r"PXK\s+0*(\d{1,9})\b", n, re.I) or re.match(r"0*(\d{3,9})_\d{12}", n)
                    if m:
                        found.append((int(m.group(1)), m.group(1)))
        except OSError:
            pass
        return found

    def next_pxk(self):
        """Số phiếu xuất kho kế tiếp = số lớn nhất đã có + 1, giữ cách viết (số 0 đầu) của số hồ sơ gần nhất. Chưa có số nào thì ''."""
        nums = self.pxk_numbers()
        if not nums:
            return ""
        top = max(n for n, _ in nums)
        width = max((len(raw) for n, raw in nums if n == top and raw.startswith("0")), default=0)
        width = width or max((len(str(r.get("pxkNo") or "")) for r in self.records if str(r.get("pxkNo") or "").startswith("0")), default=0)
        return str(top + 1).zfill(width)

    def declaration_entries(self):
        """Mọi tờ khai đang có trên ổ đĩa dưới dạng hồ sơ để hiển thị (Danh mục theo tháng / theo khách dùng chung nguồn với 'Tờ khai đang có').
        Có hồ sơ đã lưu khớp thư mục thì lấy thông tin hồ sơ; không thì dựng từ tên thư mục/file. Mỗi mục có '_path' (thư mục thật),
        'customer' (mã khách nếu nhận ra, ngược lại '') và '_label' (tên hiện)."""
        out = []
        for o in self.declaration_folders():
            rec = dict(o["record"]) if o["record"] else {}
            key = rec.get("customer") or next((k for k, p in PROFILES.items() if self._khach_match(p, o["customer"])), "")
            parts = os.path.normpath(o["path"]).split(os.sep)
            mon = next((re.match(r"(\d{4})_Thang_(\d{2})", x) for x in parts if re.match(r"\d{4}_Thang_\d{2}", x)), None)
            day = rec.get("docDate") or self.guess_date(o["day"], mon.group(1) if mon else None) or (f"{mon.group(1)}-{mon.group(2)}-01" if mon else "")
            rec.update({"customer": key, "_label": PROFILES[key].get("label", key) if key in PROFILES else o["customer"], "_dir": o["customer"],
                        "docDate": day, "tkNo": rec.get("tkNo") or o.get("tk") or "", "_path": o["path"], "_status": o.get("status", "")})
            out.append(rec)
        out.sort(key=lambda r: (str(r.get("docDate") or ""), r["_path"]), reverse=True)
        return out

    # ---- Sắp xếp lại thư mục cũ theo kiểu thống nhất: <Khách>/<yyyy>_Thang_<mm>/<yyyy-mm-dd> -------------------------
    @staticmethod
    def guess_date(text, default_year=None):
        """Ngày trong một tên thư mục/file: 2026-10-29, 20261029, 29.10.2026, 29-10-26, 29.10 (năm lấy default_year). None nếu không thấy."""
        t = str(text)
        def ok(y, m, d):
            try:
                return datetime.date(int(y), int(m), int(d)).strftime("%Y-%m-%d")
            except ValueError:
                return None
        m = re.search(r"(?<!\d)(20\d{2})[-_.]?(\d{2})[-_.]?(\d{2})(?!\d)", t)
        if m and ok(*m.groups()):
            return ok(*m.groups())
        m = re.search(r"(?<!\d)(\d{1,2})[-_.](\d{1,2})[-_.](20\d{2}|\d{2})(?!\d)", t)
        if m:
            y = m.group(3) if len(m.group(3)) == 4 else "20" + m.group(3)
            if ok(y, m.group(2), m.group(1)):
                return ok(y, m.group(2), m.group(1))
        m = re.search(r"(?<!\d)(\d{1,2})[-_.](\d{1,2})(?![\d.])", t)
        if m and default_year and ok(default_year, m.group(2), m.group(1)):
            return ok(default_year, m.group(2), m.group(1))
        return None

    def _folder_date(self, path, cust_dir):
        """(ngày, nguồn): tên thư mục (và các thư mục cha trong khách) -> tên file -> ngày sửa file mới nhất."""
        parts = os.path.relpath(path, cust_dir).split(os.sep) if path != cust_dir else []
        year = next((m.group(1) for part in parts for m in [re.search(r"(20\d{2})", part)] if m), None)
        for part in reversed(parts):
            d = self.guess_date(part, year)
            if d:
                return d, "tên thư mục"
        names = []
        for dp, _ds, fs in os.walk(path):
            names += [(os.path.join(dp, f), f) for f in fs if not f.startswith((".", "~$"))]
        for _fp, f in sorted(names, key=lambda x: x[1]):
            d = self.guess_date(f, year)
            if d:
                return d, "tên file"
        mt = [os.path.getmtime(fp) for fp, _f in names if os.path.exists(fp)]
        if mt:
            return datetime.date.fromtimestamp(max(mt)).strftime("%Y-%m-%d"), "ngày sửa file (kiểm tra lại)"
        return datetime.date.today().strftime("%Y-%m-%d"), "không có file (kiểm tra lại)"

    def plan_reorganize(self):
        """Kế hoạch đưa các thư mục khách cũ về <Khách>/<yyyy>_Thang_<mm>/<yyyy-mm-dd>. Chưa làm gì trên ổ đĩa.
        Mỗi mục: {customer, src, dst, date, nguon, loai ('thu_muc'|'file')}. Thư mục đã đúng chỗ thì bỏ qua."""
        root = self.customs_root()
        skip = {CUSTOMS_ROOT, "MAU_CHUNG_TU", GENERATED_DIR, "_KIEM_TRA"}
        roots = [root]
        nested = os.path.join(root, CUSTOMS_ROOT)
        if os.path.isdir(nested):
            roots.append(nested)
        plan, taken = [], set()
        def target(cust, day):
            base = os.path.join(root, cust, f"{day[:4]}_Thang_{day[5:7]}", day)
            dst, n = base, 2
            while os.path.normcase(dst) in taken or os.path.exists(dst):
                dst = f"{base}_{n}"
                n += 1
            taken.add(os.path.normcase(dst))
            return dst
        def standard(path, cust_dir):
            rel = os.path.relpath(path, cust_dir).split(os.sep)
            return len(rel) == 2 and re.fullmatch(r"\d{4}_Thang_\d{2}", rel[0]) and re.match(r"\d{4}-\d{2}-\d{2}", rel[1]) and os.path.normcase(os.path.dirname(cust_dir)) == os.path.normcase(root)
        folders = self.declaration_folders()
        by_cust = {}
        for o in folders:
            by_cust.setdefault(o["customer"], []).append(o)
        for rt in roots:
            try:
                custs = sorted(d for d in os.listdir(rt) if not d.startswith("_") and d.upper() not in skip and os.path.isdir(os.path.join(rt, d)))
            except OSError:
                custs = []
            for cust in custs:
                cdir = os.path.join(rt, cust)
                for o in by_cust.get(cust, []):
                    path = o["path"]
                    if os.path.normcase(path).startswith(os.path.normcase(cdir) + os.sep) or os.path.normcase(path) == os.path.normcase(cdir):
                        if path == cdir or not os.path.isdir(path):
                            continue
                        if standard(path, cdir):
                            continue
                        day, src = self._folder_date(path, cdir)
                        plan.append({"customer": cust, "src": path, "dst": target(cust, day), "date": day, "nguon": src, "loai": "thu_muc"})
                # file nằm lẻ trong thư mục khách: gom theo ngày
                try:
                    loose = [f for f in os.listdir(cdir) if os.path.isfile(os.path.join(cdir, f)) and not f.startswith((".", "~$"))]
                except OSError:
                    loose = []
                if loose and any(os.path.isdir(os.path.join(cdir, d)) for d in os.listdir(cdir)):
                    groups = {}
                    for f in loose:
                        fp = os.path.join(cdir, f)
                        d = self.guess_date(f) or datetime.date.fromtimestamp(os.path.getmtime(fp)).strftime("%Y-%m-%d")
                        groups.setdefault(d, []).append(fp)
                    for d, fps in sorted(groups.items()):
                        dst = target(cust, d)
                        for fp in fps:
                            plan.append({"customer": cust, "src": fp, "dst": dst, "date": d, "nguon": "tên file / ngày sửa", "loai": "file"})
        return plan

    def apply_reorganize(self, plan):
        """Di chuyển theo kế hoạch (không ghi đè: trùng tên thì thêm _2, _3…). Ghi nhật ký để hoàn tác. Trả (số mục đã chuyển, đường dẫn nhật ký)."""
        moves = []
        for it in plan:
            src, dst = it["src"], it["dst"]
            if not os.path.exists(src):
                continue
            os.makedirs(dst if it["loai"] == "file" else os.path.dirname(dst), exist_ok=True)
            if it["loai"] == "file":
                final = os.path.join(dst, os.path.basename(src))
                stem, ext = os.path.splitext(final)
                n = 2
                while os.path.exists(final):
                    final = f"{stem}_{n}{ext}"
                    n += 1
            else:
                final = dst
                n = 2
                while os.path.exists(final):
                    final = f"{dst}_{n}"
                    n += 1
            shutil.move(src, final)
            moves.append({"src": src, "dst": final})
            for r in self.records:  # hồ sơ đã lưu trỏ vào thư mục cũ thì trỏ sang chỗ mới
                f = r.get("folder")
                if f and it["loai"] == "thu_muc" and os.path.normcase(self.rel_to_abs(f)) == os.path.normcase(src):
                    r["folder"] = os.path.join(CUSTOMS_ROOT, os.path.relpath(final, self.customs_root()))
        logdir = os.path.join(self.customs_root(), "_NHAT_KY_SAP_XEP")
        os.makedirs(logdir, exist_ok=True)
        log = os.path.join(logdir, datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + ".json")
        with open(log, "w", encoding="utf-8") as f:
            json.dump({"moves": moves}, f, ensure_ascii=False, indent=1)
        if moves:
            with contextlib.suppress(Exception):
                self.save_records()
        return len(moves), log

    def latest_reorganize_log(self):
        logdir = os.path.join(self.customs_root(), "_NHAT_KY_SAP_XEP")
        try:
            logs = sorted(n for n in os.listdir(logdir) if n.endswith(".json") and not n.endswith(".da_hoan_tac.json"))
        except OSError:
            return ""
        return os.path.join(logdir, logs[-1]) if logs else ""

    def undo_reorganize(self, log=None):
        """Đưa các mục của lần sắp xếp gần nhất về chỗ cũ. Trả số mục đã hoàn tác."""
        log = log or self.latest_reorganize_log()
        if not log:
            raise ValueError("Chưa có lần sắp xếp nào để hoàn tác.")
        with open(log, encoding="utf-8") as f:
            moves = json.load(f).get("moves", [])
        n = 0
        for m in reversed(moves):
            if os.path.exists(m["dst"]) and not os.path.exists(m["src"]):
                os.makedirs(os.path.dirname(m["src"]), exist_ok=True)
                shutil.move(m["dst"], m["src"])
                n += 1
                for r in self.records:
                    f = r.get("folder")
                    if f and os.path.normcase(self.rel_to_abs(f)) == os.path.normcase(m["dst"]):
                        r["folder"] = os.path.join(CUSTOMS_ROOT, os.path.relpath(m["src"], self.customs_root()))
        if n:
            with contextlib.suppress(Exception):
                self.save_records()
        os.replace(log, log[:-5] + ".da_hoan_tac.json")
        return n

    def get_record_folder_path(self, rec):
        """Thư mục của một hồ sơ: HAI_QUAN / <Khách> / <Năm>_Thang_<mm> / <Ngày làm tờ khai>.

        Thư mục khách và tháng chỉ tạo khi chưa có. Hồ sơ đã lưu giữ nguyên thư mục của nó (kể cả khi sau này đổi
        tên gọi khách); hồ sơ làm từ bản cũ vẫn dùng thư mục kiểu cũ nếu thư mục đó đang có trên máy."""
        rel = rec.get("folder")
        if not rel:
            i = self.find_record(rec)
            saved = self.records[i] if i >= 0 else None
            if saved and saved.get("folder"):
                rel = saved["folder"]
            elif saved and os.path.isdir(self.legacy_folder_path(saved)):
                return self.legacy_folder_path(saved)
            else:
                rel = self.new_record_folder(rec)
        return self.rel_to_abs(rel)

    def find_record(self, rec):
        """Vị trí hồ sơ đã lưu trùng với `rec`: cùng mã hồ sơ, hoặc cùng khách + cùng PO + cùng ngày khai.
        (Một PO có thể khai nhiều ngày khác nhau: mỗi ngày là một hồ sơ riêng.)"""
        for i, r in enumerate(self.records):
            if rec.get("id") and r.get("id") == rec["id"]:
                return i
        for i, r in enumerate(self.records):
            if (r.get("customer") == rec.get("customer") and r.get("poNumber") == rec.get("poNumber")
                    and (r.get("docDate") or "") == (rec.get("docDate") or "")):
                return i
        return -1

    def new_record_folder(self, rec):
        """Đường dẫn (tương đối) cho hồ sơ mới. Cùng khách, cùng ngày, khác PO thì thêm _2, _3… để không lẫn file."""
        dt = str(rec.get("docDate") or "")
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", dt):
            dt = datetime.date.today().strftime("%Y-%m-%d")
        cust = rec.get("customer") or "KHACH"
        name = re.sub(r'[\\/:*?"<>|]+', "_", str(PROFILES.get(cust, {}).get("label") or cust)).strip(" .") or "KHACH"
        base = os.path.join(CUSTOMS_ROOT, name, f"{dt[:4]}_Thang_{dt[5:7]}", dt)
        used = {r.get("folder") for r in self.records if r.get("customer") == cust and r.get("folder")}
        rel, n = base, 2
        while rel in used:
            rel = f"{base}_{n}"
            n += 1
        return rel

    def legacy_folder_path(self, rec):
        """Cách đặt thư mục của các bản trước (01_WORKING… / 02_ARCHIVE…), chỉ để tìm lại hồ sơ cũ."""
        dt = (rec.get("docDate") or "2026-10-30").replace("-", "")
        yr, mm = dt[:4], dt[4:6]
        cust_up = (rec.get("customer") or "SHIRAI").upper()
        clean_po = re.sub(r"[^a-zA-Z0-9_-]", "", str(rec.get("poNumber") or "PO"))[:28]
        if rec.get("zone") == "WORKING":
            rel = os.path.join("01_WORKING_LAM_CHUNG_TU", f"Nam_{yr}", f"Thang_{mm}", f"{cust_up}_PO-{clean_po}_{dt}")
        else:
            pxk = f"_PXK-{rec['pxkNo']}" if rec.get("pxkNo") else ""
            hd = f"_HD-{rec['hdNo']}" if rec.get("hdNo") else ""
            tk = f"_TK-{rec['tkNo']}" if rec.get("tkNo") else ""
            rel = os.path.join("02_ARCHIVE_SAU_PHAT_HANH", f"Nam_{yr}", f"KhachHang_{cust_up}", f"Thang_{mm}", f"{dt}_{cust_up}_PO-{clean_po}{pxk}{hd}{tk}")
        return os.path.join(self.base_dir, rel)

