# 4. BỘ XUẤT 6 FILE EXCEL ĐẦY ĐỦ 100% CÔNG THỨC & ĐỊNH DẠNG NHƯ BẢN GỐC
# ==============================================================================
THIN_SIDE = Side(style="thin", color="000000")
MED_SIDE = Side(style="medium", color="000000")
BOX_BORDER = Border(left=THIN_SIDE, right=THIN_SIDE, top=THIN_SIDE, bottom=THIN_SIDE)


def make_fill(hex_color):
    return PatternFill(start_color=hex_color, end_color=hex_color, fill_type="solid")


def apply_region_outer_edge(ws, c1, r1, c2, r2, t=False, b=False, l=False, r=False):
    for row_i in range(r1, r2 + 1):
        for col_i in range(c1, c2 + 1):
            cell = ws.cell(row=row_i, column=col_i)
            cur = cell.border or Border()
            cell.border = Border(
                top=THIN_SIDE if (t and row_i == r1) else cur.top,
                bottom=THIN_SIDE if (b and row_i == r2) else cur.bottom,
                left=THIN_SIDE if (l and col_i == c1) else cur.left,
                right=THIN_SIDE if (r and col_i == c2) else cur.right,
            )


def get_vat_and_pxk_ids(rec):
    cust = rec.get("customer", "shirai")
    dt_parts = (rec.get("docDate") or datetime.date.today().strftime("%Y-%m-%d")).split("-")
    d = int(dt_parts[2]) if len(dt_parts) == 3 else datetime.date.today().day
    m = int(dt_parts[1]) if len(dt_parts) == 3 else datetime.date.today().month
    dd = f"{d:02d}"
    mm = f"{m:02d}"
    short_d = f"{d}.{m}"
    items = rec.get("items", [])
    is_pallet = len(items) > 0 and all(x.get("unit") == "cái" for x in items)
    if cust == "kodi":
        return f"kodi{d},{m}", f"kodi{dd}/{mm} ống"
    if cust == "tesa":
        suf = " pl" if is_pallet else ""
        return f"tesa{d}.{m}{suf}", f"tesa{d}.{m}{suf}"
    if cust not in BUILTIN_CUSTOMERS:
        if is_arizon(PROFILES.get(cust, {})):  # Arizon: VAT 'HĐ arizon16/10 xk', PXK 'arizon16/10'
            return f"HĐ arizon{dd}/{mm} xk", f"arizon{dd}/{mm}"
        if is_best_docset(rec):  # Best: 'best 02.11 POS261008053' (nhiều PO thì nối liền các số PO)
            pos = "".join(p for p, _ in rec_po_list(rec))
            return f"{cust} {dd}.{mm} {pos}".strip(), f"{cust} {dd}.{mm} {pos}".strip()
        return f"{cust}{d}.{m}", f"{cust}{d}.{m}"
    return f"shirai ngày {short_d}", f"Shirai ngày {short_d}"


