def build_plx_sheet(wb, rec, sheet_name="PLX"):
    if is_arizon_plx(PROFILES.get(rec.get("customer"), {})):
        return build_plx_arizon_sheet(wb, rec, sheet_name)
    ws = wb.create_sheet(title=sheet_name[:31])
    dt_parts = (rec.get("docDate") or datetime.date.today().strftime("%Y-%m-%d")).split("-")
    dd, mm, yy = (dt_parts[2], dt_parts[1], dt_parts[0]) if len(dt_parts) == 3 else ("30", "10", "2026")
    d_short = f"{int(dd)}/{int(mm)}/{yy}"
    no = rec.get("hdNo") or ""
    items = rec.get("items", [])
    unit = (items[0].get("unit") if items else None) or "ống"

    widths = [64, 18, 13, 16, 20]
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    def put(addr, merge_rng, val, sz, bold=False, italic=False, align_h="center"):
        if merge_rng:
            ws.merge_cells(merge_rng)
        c = ws[addr]
        c.value = val
        c.font = Font(name="Times New Roman", size=sz, bold=bold, italic=italic)
        c.alignment = Alignment(horizontal=align_h, vertical="center", wrap_text=True)
        return c

    put("A1", "A1:E1", "  Phụ lục X", 13, True)
    put("A2", "A2:E2", "BẢN KHAI BÁO XUẤT XỨ CỦA NHÀ SẢN XUẤT/NHÀ CUNG CẤP NGUYÊN LIỆU TRONG NƯỚC", 11, True)
    put("A3", "A3:E3", "(ban hành kèm theo Thông tư số 05/2018/TT-BCT ngày 03 tháng 4 năm 2018  quy định về xuất xứ hàng hóa)", 12, italic=True)
    put("A4", None, f"                                                   Số:     {no} ngày {d_short}", 13, italic=True, align_h="left")
    put("A5", None, f"Tên nhà sản xuất: {HT_NAME}", 13, align_h="left")
    put("A6", None, f"Mã số Doanh nghiệp : {MST_HT}", 13, align_h="left")
    put("A7", None, "Số lượng hàng hóa: ", 13, align_h="left")
    put("A8", None, "Trị giá hàng hóa (FOB):        ", 13, align_h="left")
    put("A9", "A9:E9", f"Hóa đơn giá trị gia tăng số:  {no} ngày {d_short} {HT_NAME} xác nhận rằng nguyên liệu/hàng hóa (1) có tên sau:  ", 13, align_h="left")
    ws.row_dimensions[9].height = 41.25

    hr = 11
    first = hr + 1
    last = hr + len(items)  # dòng hàng chiếm các hàng first..hr+n; hàng tổng nằm ngay dưới
    tot = last + 1
    acc_fmt = '_(* #,##0_);_(* \\(#,##0\\);_(* \\-??_);_(@_)'

    ws["B7"] = f"=D{tot}"
    ws["B7"].font = Font(name="Times New Roman", size=12, bold=True)
    ws["B7"].number_format = acc_fmt
    ws["C7"] = unit
    ws["B8"] = f"=E{tot}"
    ws["B8"].font = Font(name="Times New Roman", size=12, bold=True)
    ws["B8"].number_format = acc_fmt
    ws["C8"] = "VNĐ"

    heads = ["Tên sản phẩm", "PO", "Mã HS", f"Số lượng ({unit})", "Trị giá hàng hóa (FOB)"]
    ws.row_dimensions[hr].height = 54
    for i, h in enumerate(heads, 1):
        c = ws.cell(row=hr, column=i, value=h)
        c.font = Font(name="Times New Roman", size=12, bold=True)
        c.alignment = Alignment(horizontal="left" if i == 2 else "center", vertical="center", wrap_text=True)
        c.border = BOX_BORDER

    for idx, it in enumerate(items):
        r = first + idx
        ws.row_dimensions[r].height = 48
        hs_val = int(it["hs"]) if str(it.get("hs", "")).isdigit() else it.get("hs", "")
        vals = [it.get("ten_hq") or it["ten_sp"], it.get("po", ""), hs_val, it.get("qty", 0), it.get("amount", 0)]
        for c_i, v in enumerate(vals, 1):
            c = ws.cell(row=r, column=c_i, value=v)
            c.font = Font(name="Times New Roman", size=12 if c_i <= 4 else 13)
            c.alignment = Alignment(horizontal="left" if c_i <= 2 else "center", vertical="center", wrap_text=True)
            c.border = BOX_BORDER
            if c_i == 4:
                c.number_format = "#,##0"
            elif c_i == 5:
                c.number_format = acc_fmt

    ws.row_dimensions[tot].height = 36
    for c_i in range(1, 6):
        ws.cell(row=tot, column=c_i).border = BOX_BORDER
    put(f"A{tot}", None, "Tổng cộng", 11, True, align_h="left")
    if items:
        c_d = put(f"D{tot}", None, f"=SUM(D{first}:D{last})", 12, True, align_h="center")
        c_d.number_format = "#,##0"
        c_e = put(f"E{tot}", None, f"=SUM(E{first}:E{last})", 13, True, align_h="center")
        c_e.number_format = acc_fmt

    t = tot + 2
    ws.row_dimensions[t].height = 70
    put(
        f"A{t}",
        f"A{t}:E{t}",
        "      Khai tại văn bản này, được sản xuất tại nhà máy của Công ty chúng tôi tại (2) Lô CN-15.1, KCN Thuận Thành II, Phường Mão Điền, Thành phố Bắc Ninh, Việt Nam có xuất xứ Việt Nam và đáp ứng tiêu chí CTH theo Thông tư số 05 /2018/TT-BCT ngày 03 tháng 4 năm 2018;đáp ứng tiêu chí CTSH+RVC 35% theo AIFTA/TT15/2010/TT-BTC ngày 15/04/2010; EVFTA// 11/2020/TT-BCT ngày 15/06/2020; tiêu chí RVC 40% theo quy định tại Chương Quy tắc xuất xứ hàng hóa trong (4) hiệp định ACFTA điểm a khoản 1 điều 7 thông tư 12/2019/TT-BCT ngày 30/07/2019 của  bộ Công Thương.",
        11,
        align_h="left",
    )
    put(f"A{t+1}", f"A{t+1}:E{t+1}", "Công ty cam kết thông tin khai báo trên là đúng và chịu trách nhiệm trước pháp luật về thông tin đã khai", 11, align_h="left")
    put(f"B{t+2}", f"B{t+2}:E{t+2}", f"   Bắc Ninh, ngày {dd} tháng {mm}  năm {yy}", 11, italic=True, align_h="center")
    put(f"B{t+4}", f"B{t+4}:E{t+4}", "Người đại diện theo pháp luật của thương nhân", 11, align_h="center")
    return ws


def build_customs_b11_sheet(wb, rec, sheet_name="ToKhai_B11"):
    ws = wb.create_sheet(title=sheet_name[:31])
    is_tesa = rec.get("customer", "tesa") == "tesa"
    prof = PROFILES["tesa"] if is_tesa else PROFILES.get(rec["customer"], PROFILES["tesa"])
    c_cfg = prof.get("customs") or PROFILES["tesa"]["customs"]
    dt_parts = (rec.get("docDate") or datetime.date.today().strftime("%Y-%m-%d")).split("-")
    dt_vn = f"{dt_parts[2]}/{dt_parts[1]}/{dt_parts[0]}" if len(dt_parts) == 3 else rec.get("docDate", "")
    pxk_no = rec.get("pxkNo") or "00000287"
    items = rec.get("items", [])

    widths = [34, 26, 70, 16, 14, 16, 16, 20]
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w

    r = 1

    def write_title(text):
        nonlocal r
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=8)
        c = ws.cell(row=r, column=1, value=text)
        c.font = Font(name="Arial", size=12, bold=True)
        c.fill = make_fill("CCFFFF")
        r += 1

    def write_kv(k, v, note=""):
        nonlocal r
        ws.cell(row=r, column=1, value=k).font = Font(name="Arial", size=11)
        ws.cell(row=r, column=2, value=v).font = Font(name="Arial", size=11, bold=True)
        if note:
            ws.cell(row=r, column=3, value=note).font = Font(name="Arial", size=10, italic=True, color="9B1C1C")
        r += 1

    tot_kien = sum(x.get("kien", 0) for x in items) if is_tesa else lot_totals(rec)["kien"]
    tot_gross = sum(x.get("gross") or x.get("net") or 0 for x in items)
    tot_amt = sum(x.get("amount", 0) for x in items)
    pos = [p for p, _ in rec_po_list(rec)]

    write_title("1. THÔNG TIN CHUNG TỜ KHAI (nhập vào VNACCS)")
