    ws.row_dimensions[r + 2].height = 33
    r += 4
    put(f"A{r}", f"A{r}:B{r}", "Điểm xuất phát:", 11)
    put(f"C{r}", None, "Điểm giao hàng", 11)
    put(f"D{r}", f"D{r}:F{r}", "Điều kiện giao hàng", 11)
