    _outline(ws, 2, 1, r - 2, 3)
    _outline(ws, 2, 4, r - 2, 6)
    _outline(ws, r - 1, 1, r + 1, 2)
    _outline(ws, r - 1, 3, r + 1, 3)
    _outline(ws, r - 1, 4, r + 3, 6)
    _outline(ws, r + 2, 1, r + 3, 3)
    r += 4

    hr = r
