# Từ khóa tiêu đề cột Invoice/PKL (đã bỏ dấu, viết hoa); thứ tự = ưu tiên khi một tiêu đề khớp nhiều trường
INVOICE_HEADER_KEYS = [
    ("amount", ["THANH TIEN", "AMOUNT", "TRI GIA"]),
    ("price", ["DON GIA", "UNIT PRICE", "PRICE"]),
    ("net", ["N.W", "NW", "NET WEIGHT", "NET", "TRONG LUONG TINH", "KHOI LUONG TINH", "KL TINH"]),
    ("gross", ["G.W", "GW", "GROSS", "CA BI", "TRONG LUONG CA", "KHOI LUONG CA"]),
    ("kien", ["SO KIEN", "KIEN", "PACKAGE", "PACKAGES", "CTNS", "CARTON", "PKGS"]),
    ("kg", ["CAN NANG", "TRONG LUONG", "KHOI LUONG", "KG/CHIEC", "UNIT WEIGHT", "WEIGHT"]),
    ("qty", ["SO LUONG", "QTY", "QUANTITY", "SL"]),
    ("unit", ["DVT", "DON VI TINH", "DON VI", "UNIT", "UOM"]),
    ("hs", ["MA HS", "HS CODE", "HS"]),
    ("po", ["SO PO", "PO NO", "PO"]),
    ("code", ["MA HANG", "MA SP", "MA SAN PHAM", "ITEM CODE", "PART NO", "CODE", "MA"]),
    ("name", ["TEN HANG", "TEN SAN PHAM", "TEN SP", "HANG HOA", "MO TA", "DESCRIPTION", "TEN"]),
]

PO_NUMBER_HINT_RE = re.compile(
    r"(?:P\.?\s?O\.?\s*(?:No\.?|Number|#)?|Purchase\s*Order(?:\s*No\.?)?|S[ốo]\s*(?:PO|ĐĐH|DDH|đơn\s*hàng|don\s*hang)"
    r"|Đơn\s*đặt\s*hàng\s*(?:số)?|Don\s*dat\s*hang\s*(?:so)?)\s*[:#.]?\s*([A-Za-z0-9][A-Za-z0-9/_.-]{3,})",
    re.I,
)


def parse_vn_number(s):
    """'1.000' -> 1000, '31.500.000' -> 31500000, '1,5' -> 1.5, '1,234.50' -> 1234.5, 12 -> 12."""
    if isinstance(s, (int, float)):
        return s
    t = re.sub(r"[^\d.,-]", "", str(s or ""))
    if not re.search(r"\d", t):
        return 0
    if "." in t and "," in t:
        dec = "." if t.rfind(".") > t.rfind(",") else ","
        t = t.replace("," if dec == "." else ".", "").replace(dec, ".")
    else:
        sep = "." if "." in t else ("," if "," in t else "")
        if sep:
            parts = t.split(sep)
            if len(parts) > 2 or (len(parts[-1]) == 3 and parts[0].lstrip("-") not in ("", "0")):
                t = t.replace(sep, "")
            else:
                t = t.replace(sep, ".")
    try:
        v = float(t)
    except ValueError:
        return 0
    return int(v) if v == int(v) else v


def _num_or_zero(v):
    try:
        return parse_vn_number(v) if v not in (None, "") else 0
    except Exception:
        return 0


def _xml_local(tag):
    return str(tag).rsplit("}", 1)[-1]


def _xml_find(node, *names):
    if node is None:
        return None
    for el in node.iter():
        if _xml_local(el.tag) in names:
            return el
    return None


def _xml_text(node, *names):
    el = _xml_find(node, *names)
    return (el.text or "").strip() if el is not None and el.text else ""


def learn_from_einvoice_xml(file_path):
    """Đọc XML hóa đơn VAT / PXK kiêm VCNB điện tử (TT78, BKAV/VNPT/Viettel... cùng chuẩn thẻ)."""
    import xml.etree.ElementTree as ET

    root = ET.parse(file_path).getroot()
    ttchung = _xml_find(root, "TTChung")
    mau_so = _xml_text(ttchung, "KHMSHDon")
    ky_hieu = _xml_text(ttchung, "KHHDon")
    doc_type = "pxk" if mau_so == "6" or _xml_find(root, "LDDNBo", "TNVChuyen", "PTVChuyen") is not None else "vat"
    buyer = _xml_find(root, "NMua", "NNhan")
    profile = {
        "name": _xml_text(buyer, "Ten", "TNNhan"),
        "mst": _xml_text(buyer, "MST"),
        "addr": _xml_text(buyer, "DChi"),
        "emails": _xml_text(buyer, "DCTDTu"),
        "symbol": f"{mau_so}{ky_hieu}" if ky_hieu else "",
    }
    if doc_type == "pxk":
        # địa chỉ trên PXK là kho nhận hàng; địa chỉ đăng ký lấy từ hóa đơn VAT
        profile["addrKho"] = _xml_text(root, "DCNHang", "DChiNHang") or profile.pop("addr")
        profile["driver"] = _xml_text(root, "TNVChuyen")
        profile["xe"] = _xml_text(root, "PTVChuyen")
        profile["symbol"] = profile["symbol"] or "6C26NAA"
    items = []
    for el in root.iter():
        if _xml_local(el.tag) != "HHDVu":
            continue
        name = _xml_text(el, "THHDVu")
        qty = _num_or_zero(_xml_text(el, "SLuong"))
        if not name or _xml_text(el, "TChat") in ("2", "3", "4"):
            continue
        items.append({
            "code": _xml_text(el, "MHHDVu"),
            "name": name,
            "unit": _xml_text(el, "DVTinh"),
            "qty": qty,
            "price": _num_or_zero(_xml_text(el, "DGia")),
        })
    meta = {"doc_type": doc_type, "so": _xml_text(ttchung, "SHDon"), "ngay": _xml_text(ttchung, "NLap")}
    return {"source": os.path.basename(file_path), "kind": doc_type, "profile": profile, "items": items, "meta": meta}


def _match_invoice_header(row):
    """Tìm dòng tiêu đề Invoice/PKL. Trả về {trường: [các cột]}; một trường có thể lặp (VD 2 cột 'Mã hàng')."""
    cols = {}
    for c_i, v in enumerate(row):
        h = re.sub(r"\s+", " ", strip_accents_upper(v or "")).strip()
        if not h or len(h) > 60:
            continue
        for field, keys in INVOICE_HEADER_KEYS:
            if any(re.search(r"(?<![A-Z])" + re.escape(k) + r"(?![A-Z])", h) for k in keys):
                cols.setdefault(field, []).append(c_i)
                break
    return cols if ("name" in cols and ("qty" in cols or "price" in cols)) else None


DATE_IN_TEXT_RE = re.compile(r"(?<!\d)(\d{1,2})/(\d{1,2})/(20\d{2})(?!\d)")


def _sheet_date(rows):
    """Ngày của chứng từ trên sheet: ngày dd/mm/yyyy ở phần đầu, không có thì ngày lớn nhất trong sheet."""
    best = None
    for r in rows[:15]:
        for v in r:
            m = DATE_IN_TEXT_RE.search(str(v or "")) if isinstance(v, str) else None
            if m:
                try:
                    d = datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
                except ValueError:
                    continue
                best = max(best, d) if best else d
    if best:
        return best
    for r in rows:
        for v in r:
            if isinstance(v, datetime.datetime):
                best = max(best, v.date()) if best else v.date()
    return best or datetime.date(1900, 1, 1)


def _learn_norm_table(rows):
    """Bảng định mức đóng gói kiểu 'Mã code | Quy cách | Số lượng ống / 1 túi' -> {mã: SL/kiện}."""
    for i, r in enumerate(rows[:10]):
        heads = [strip_accents_upper(v or "") for v in r]
        c_code = next((k for k, h in enumerate(heads) if re.search(r"(?<![A-Z])MA(?![A-Z])", h)), None)
        c_div = next((k for k, h in enumerate(heads) if re.search(r"/\s*1\s*(TUI|KIEN|BAO|THUNG|BO|CUON)", h)), None)
        if c_code is None or c_div is None:
            continue
        out = {}
        for row in rows[i + 1:]:
            code = str(row[c_code] or "").strip() if c_code < len(row) else ""
            div = _num_or_zero(row[c_div]) if c_div < len(row) else 0
            if code and isinstance(div, (int, float)) and div > 0:
                out[code] = div
        return out
    return {}


def _learn_party_from_sheet(rows):
    """Thông tin khách trên Invoice/biên bản Excel: tên + địa chỉ dưới ô 'Người nhận hàng', MST, 'Bên A'."""
    prof = {}
    for i, r in enumerate(rows[:30]):
        for j, v in enumerate(r):
            t = str(v or "").strip()
            u = strip_accents_upper(t)
            if not prof.get("name") and re.match(r"^NGUOI (NHAN HANG|NHAP KHAU|MUA)", u) and i + 1 < len(rows):
                below = str((rows[i + 1][j] if j < len(rows[i + 1]) else "") or "").strip()
                if below and "HONG THIEN" not in strip_accents_upper(below):
                    prof["name"] = below
                    addr = str((rows[i + 2][j] if i + 2 < len(rows) and j < len(rows[i + 2]) else "") or "").strip()
                    if addr and not re.match(r"^PHUONG (TIEN|THUC)", strip_accents_upper(addr)):
                        prof["addr"] = addr
            m = re.search(r"(BEN A|KHACH HANG|BEN MUA)[^:]*:\s*(.+)", u)
            if not prof.get("name") and m and "HONG THIEN" not in m.group(2):
                prof["name"] = t[t.index(":") + 1:].strip()
            m = re.search(r"MA SO THUE\W*(\d{10}(?:-\d{3})?)", u)
            if m and m.group(1) != MST_HT and not prof.get("mst"):
                prof["mst"] = m.group(1)
            m = re.match(r"^DIA CHI\W*(.+)", u)
            if m and prof.get("name") and not prof.get("addr") and "HONG THIEN" not in u and "THUAN THANH" not in u:
                prof["addr"] = re.sub(r"^\s*Đ[iị]a ch[iỉ]\W*", "", t, flags=re.I).strip()
    return prof


def learn_from_invoice_excel(file_path, ignore_norms=False):
    """Đọc Invoice / Bảng kê PKL Excel của khách (mọi sheet): mã, tên, đơn giá, kg/chiếc, SL/kiện, số PO, bì.
    Cùng một mặt hàng xuất hiện ở nhiều sheet thì sheet có ngày mới nhất được ưu tiên."""
    wb = openpyxl.load_workbook(file_path, data_only=True)
    try:
        wbf = openpyxl.load_workbook(file_path)  # bản công thức: lấy 'số cái mỗi kiện' từ công thức Số kiện (=ROUNDUP(F14/10,0) -> 10)
    except Exception:
        wbf = None
    sheets, norms, profile, ddh = [], {}, {}, []
    for ws in wb.worksheets:
        rows = [tuple(r) for r in ws.iter_rows(values_only=True)]
        # Invoice không có cột PO nhưng ghi 'Số ĐĐH: <PO>' ở phần đầu (kiểu Best); bỏ dòng bị ẩn (PO cũ còn sót)
        for i, r in enumerate(rows[:20]):
            if ws.row_dimensions[i + 1].hidden:
                continue
            for v in r:
                m = re.search(r"S[ốo]\s*(?:ĐĐH|DDH)\s*:\s*([A-Za-z0-9][A-Za-z0-9/_.-]{3,})", str(v or ""))
                if m:
                    ddh.append(m.group(1))
        norms.update(_learn_norm_table(rows))
        for k, v in _learn_party_from_sheet(rows).items():
            profile.setdefault(k, v)
        h_idx, cols = -1, None
        for i, r in enumerate(rows[:60]):
            cols = _match_invoice_header(r)
            if cols:
                h_idx = i
                break
        if not cols:
            continue
        items, blank = [], 0
        frows = [tuple(x) for x in wbf[ws.title].iter_rows(values_only=True)] if wbf is not None and ws.title in wbf.sheetnames else []
        for r_i, r in enumerate(rows[h_idx + 1:], h_idx + 1):
            def get(f):
                # Cột 'Mã hàng' hay bị gộp ô: tiêu đề ở cột này, mã nằm ở cột bên phải
                extra = [c + 1 for c in cols.get(f, []) if f == "code"]
                for c in cols.get(f, []) + extra:
                    v = r[c] if c < len(r) else None
                    if v in (None, "") or str(v).strip() in ("", "0", "#REF!"):
                        continue
                    if c in extra and not re.fullmatch(r"[A-Z0-9][A-Z0-9._/-]{4,}", str(v).strip(), re.I):
                        continue
                    return v
                return None
            name = re.sub(r"\s+", " ", str(get("name") or "")).strip()
            if not name or name.startswith("#"):
                blank += 1
                if blank >= 3:
                    break
                continue
            blank = 0
            if re.match(r"^(TONG|TOTAL|CONG|SUM)", strip_accents_upper(name)):
                break
            qty = _num_or_zero(get("qty"))
            price = _num_or_zero(get("price"))
            qty = qty if isinstance(qty, (int, float)) else 0
            price = price if isinstance(price, (int, float)) else 0
            if qty <= 0 and price <= 0:
                continue
            net = _num_or_zero(get("net"))
            gross = _num_or_zero(get("gross"))
            kien = _num_or_zero(get("kien"))
            kg = _num_or_zero(get("kg"))
            code_cell = str(get("code") or "").strip()
            mcode = re.match(r"^(\d[A-Z0-9]{9,})\s+(\S.*)$", name) if not code_cell else None
            if mcode:  # mã hàng ghi chung ô với tên ('2V01PRB000002 Ống giấy…'): tách ra
                code_cell, name = mcode.group(1), mcode.group(2).strip()
            it = {
                "code": code_cell,
                "name": name,
                "unit": str(get("unit") or "").strip(),
                "qty": qty,
                "price": price,
                "hs": re.sub(r"\D", "", str(get("hs") or "")),
                "po": str(get("po") or "").strip(),
            }
            if isinstance(kg, (int, float)) and 0 < kg < 1000:
                it["kg"] = kg
            elif qty > 0 and isinstance(net, (int, float)) and net > 0:
                it["kg"] = round(net / qty, 6)
            if qty > 0 and isinstance(net, (int, float)) and isinstance(gross, (int, float)) and gross > net > 0:
                it["tare"] = round(gross - net, 3)
            if qty > 0 and isinstance(kien, (int, float)) and kien > 0:
                div = qty / kien
                it["div"] = int(round(div)) if abs(div - round(div)) < 1e-6 else round(div, 3)
            elif r_i < len(frows) and cols.get("kien"):
                fcell = frows[r_i][cols["kien"][0]] if cols["kien"][0] < len(frows[r_i]) else None
                m = re.search(r"/\s*\(?\s*(\d+(?:\.\d+)?)\s*\)?", str(fcell)) if isinstance(fcell, str) and fcell.startswith("=") else None
                if m and float(m.group(1)) > 0:
                    it["div"] = int(float(m.group(1))) if float(m.group(1)).is_integer() else float(m.group(1))
            items.append(it)
        if items:
            sheets.append((_sheet_date(rows), ws.title, items))

    # Mới nhất trước: merge_learned_docs giữ giá trị gặp đầu tiên
    sheets.sort(key=lambda x: x[0], reverse=True)
    items = [it for _, _, its in sheets for it in its]
    for it in items:
        code = it.get("code", "")
        if code in norms and not ignore_norms:
            it["div"] = norms[code]
    # SL/kiện: ưu tiên số nguyên (sheet mới nhất có số nguyên) hơn số lẻ do làm tròn số kiện
    by_name = {}
    for it in items:
        by_name.setdefault(clean_str(it["name"]), []).append(it)
    for group in by_name.values():
        ints = [x["div"] for x in group if x.get("div") and float(x["div"]).is_integer()]
        if ints:
            for x in group:
                x["div"] = ints[0]
    with_po = next((its for _, _, its in sheets if any(x.get("po") for x in its)), [])
    pos = [it["po"] for it in with_po if it.get("po")]
    with_tare = next((its for _, _, its in sheets if any(x.get("tare") for x in its)), [])
    tares = [it["tare"] for it in with_tare if it.get("tare")]
    meta = {
        "sample_po": max(set(pos), key=pos.count) if pos else (ddh[0] if ddh else ""),
        "tare": min(set(tares), key=lambda t: (-tares.count(t), t)) if tares else 0.0,
        "sheets": [t for _, t, _ in sheets],
    }
    return {"source": os.path.basename(file_path), "kind": "invoice", "profile": profile, "items": items, "meta": meta}


def excel_to_text(file_path):
    """Chuyển Excel thành văn bản từng dòng (ô cách nhau ' | ') để dùng chung bộ đọc PO văn bản."""
    wb = openpyxl.load_workbook(file_path, data_only=True)
    out = []
    for ws in wb.worksheets:
        for r in ws.iter_rows(values_only=True):
            cells = []
            for v in r:
                if v is None or v == "":
                    continue
                if isinstance(v, float) and v.is_integer():
                    v = int(v)
                cells.append(str(v))
            if cells:
                out.append(" | ".join(cells))
    return "\n".join(out)


def read_document_text(file_path):
    ext = os.path.splitext(file_path)[1].lower()
    if ext in (".txt", ".csv"):
        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
            return f.read()
    if ext in (".xlsx", ".xlsm"):
        return excel_to_text(file_path)
    return extract_text_from_pdf_or_image_offline(file_path, table_mode=True)


def guess_po_number(text):
    m = PO_NUMBER_HINT_RE.search(text or "")
    return m.group(1).rstrip(".-/") if m else ""


def infer_po_pattern(sample_po):
    """Học dạng số PO từ 1 ví dụ: chữ giữ nguyên (mã cố định của khách), số -> \\d{n}.
    VD '03102026-01KDHT' -> '\\d{8}-\\d{1,2}KDHT'."""
    sample_po = (sample_po or "").strip()
    if not sample_po:
        return ""
    out = []
    for tok in re.findall(r"\d+|[A-Za-z]+|\s+|.", sample_po):
        if tok.isdigit():
            out.append(r"\d{1,2}" if len(tok) <= 2 else r"\d{%d}" % len(tok))
        elif tok.isspace():
            out.append(r"\s*")
        else:
            out.append(re.escape(tok))
    return r"(?<![A-Za-z0-9])" + "".join(out) + r"(?![A-Za-z0-9])"


def find_po_date(text):
    m = re.search(r"PO\s*Date\W{0,6}([23]0\d{2})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})(?!\d)", text or "", re.I)
    if m:  # 'PO Date 3026/10/02': OCR đọc nhầm chữ số đầu của năm
        return f"{int(m.group(3)):02d}/{int(m.group(2)):02d}/2{m.group(1)[1:]}"
    m = re.search(r"ng[àa]y\W{0,4}(\d{1,2})\s*th[áa]ng\s*(\d{1,2})\s*n[ăa]m\s*(\d{4})", text or "", re.I) or re.search(
        r"(?<!\d)(\d{1,2})[/.-](\d{1,2})[/.-](20\d{2})(?!\d)", text or ""
    )
    if m:
        return f"{int(m.group(1)):02d}/{int(m.group(2)):02d}/{m.group(3)}"
    # PO dạng 2026-09-11 / 2026/09/11 / 2026年8月21日: ưu tiên ngày đứng sau nhãn 'PO Date' / 'Ngày xuống đơn' / '签订日期'
    iso = r"(20\d{2})\s*[-/.年]\s*(\d{1,2})\s*[-/.月]\s*(\d{1,2})(?!\d)"
    m = re.search(r"(?:PO\s*Date|Ng[àa]y\s*xu[ốo]ng\s*đ[ơo]n|Order\s*Date|签订日期|日期)[^\n\d]{0,40}" + iso, text or "", re.I) or re.search(
        r"(?<!\d)" + iso, text or ""
    )
    return f"{int(m.group(3)):02d}/{int(m.group(2)):02d}/{m.group(1)}" if m else ""


def merge_learned_docs(results):
    """Gộp kết quả nhiều chứng từ: XML làm chuẩn cho thông tin khách, Excel PKL bổ sung định mức."""
    profile = {}
    order = sorted(results, key=lambda r: {"pxk": 0, "vat": 1}.get(r.get("kind"), 2))
    for res in order:
        for k, v in res.get("profile", {}).items():
            if v and not profile.get(k):
                profile[k] = v
    items = []

    def find(it):
        ck = clean_str(it.get("name"))
        for x in items:
            if it.get("code") and x.get("code") == it["code"]:
                return x
            if ck and clean_str(x.get("name")) == ck:
                return x
        return None

    for res in results:
        for it in res.get("items", []):
            hit = find(it)
            if hit is None:
                hit = {"code": "", "name": "", "unit": "", "price": 0, "div": 0, "kg": 0, "hs": ""}
                items.append(hit)
            for k in ("code", "name", "unit", "price", "div", "kg", "hs"):
                if it.get(k) and not hit.get(k):
                    hit[k] = it[k]
    units = [x["unit"] for x in items if x.get("unit")]
    if units and not profile.get("unit"):
        profile["unit"] = max(set(units), key=units.count)
    return {"profile": profile, "items": items, "sources": [r.get("source", "") for r in results]}


def learn_customer_from_documents(paths):
    """Phân tích danh sách file mẫu, trả về bản nháp {profile, items, sources, po_text, sample_po, errors}."""
    results, errors, po_text = [], [], ""
    for p in paths:
        ext = os.path.splitext(p)[1].lower()
        try:
            if ext == ".xml":
                results.append(learn_from_einvoice_xml(p))
                continue
            if ext in (".xlsx", ".xlsm"):
                res = learn_from_invoice_excel(p)
                if res["items"]:
                    results.append(res)
                    continue
            txt = read_document_text(p)
            if txt.strip():
                po_text += ("\n" if po_text else "") + txt
            else:
                errors.append(f"{os.path.basename(p)}: không đọc được chữ" + ("" if ocr_available() else " (PDF ảnh cần bộ OCR Tesseract-OCR cạnh file .exe)"))
        except Exception as e:
            errors.append(f"{os.path.basename(p)}: {e}")
    draft = merge_learned_docs(results)
    draft["po_text"] = po_text
    # Số PO mẫu: lấy từ cột PO của Invoice (chính xác) trước, không có mới đoán trong PO
    metas = [r.get("meta") or {} for r in results]
    draft["sample_po"] = next((m["sample_po"] for m in metas if m.get("sample_po")), "") or guess_po_number(po_text)
    draft["tare"] = next((m["tare"] for m in metas if m.get("tare")), 0.0)
    draft["errors"] = errors
    return draft


def customer_key_from_name(name, taken=()):
    words = re.findall(r"[A-Z0-9]+", strip_accents_upper(name))
    stop = {"CONG", "TY", "TNHH", "CO", "PHAN", "CP", "MTV", "VIET", "NAM", "VN", "VIETNAM", "CHI", "NHANH", "CN", "CO.", "LTD", "CORP"}
    core = [w for w in words if w not in stop]
    base = (core[0] if core else (words[0] if words else "khach")).lower()[:16]
    key, n = base, 2
    while key in taken:
        key = f"{base}{n}"
        n += 1
    return key


def find_existing_customer(store, name="", mst=""):
    """Khách đã học/thêm mới có cùng tên công ty (bỏ dấu, không phân biệt hoa thường) hoặc cùng mã số thuế. Trả mã khách hoặc ''."""
    norm = lambda t: re.sub(r"[^A-Z0-9]+", " ", strip_accents_upper(str(t or ""))).strip()
    n, m = norm(name), re.sub(r"\D", "", str(mst or ""))
    for k, p in PROFILES.items():
        if k in BUILTIN_CUSTOMERS:
            continue
        if (n and norm(p.get("name")) == n) or (m and re.sub(r"\D", "", str(p.get("mst") or "")) == m):
            return k
    return ""


def merge_learned_items(existing, new):
    """Gộp mặt hàng học thêm vào danh mục đã có của khách: trùng mã hoặc tên thì chỉ điền chỗ còn trống (giữ giá trị người dùng đã sửa), chưa có thì thêm.
    Trả (danh sách gộp, số mặt hàng thêm mới, số mặt hàng đã có được bổ sung)."""
    out = [dict(x) for x in existing]
    added = filled = 0
    for it in new:
        hit = next((x for x in out if (it.get("code") and x.get("code") == it.get("code")) or (it.get("name") and x.get("name") == it.get("name"))), None)
        if hit is None:
            out.append(dict(it))
            added += 1
            continue
        changed = False
        for k, v in it.items():
            if v not in (None, "", 0) and hit.get(k) in (None, "", 0):
                hit[k] = v
                changed = True
        filled += changed
    return out, added, filled


def build_custom_profile(key, fields):
    prof = dict(CUSTOM_PROFILE_DEFAULTS)
    if fields.get("docSet") == "best":
        prof.update(json.loads(json.dumps(BEST_DOCSET_DEFAULTS)))
    prof.update({k: v for k, v in fields.items() if v not in (None, "")})
    prof["key"] = key
    prof["file"] = key
    prof.setdefault("name", key.upper())
    prof.setdefault("label", key.capitalize())
    prof.setdefault("mst", "")
    prof.setdefault("addr", "")
    prof["addrKho"] = prof.get("addrKho") or prof["addr"]
    prof["custom"] = True
    return prof


def _name_dims(name):
    """Quy cách trong tên hàng: 'Ống giấy phi 38 x 5 x 467mm x280g' -> (['38','5','467'], '280')."""
    t = strip_accents_upper(name)
    t = re.sub(r"\([^)]*\)", " ", t)  # bỏ '(3inch)'
    m = re.search(r"(\d+(?:[.,]\d+)?)\s*(?:MM)?\s*[X*]\s*(\d+(?:[.,]\d+)?)\s*(?:MM)?(?:\s*[X*]\s*(\d+(?:[.,]\d+)?))?", t)
    dims = [d.replace(",", ".") for d in m.groups() if d] if m else []
    g = re.search(r"(\d{2,4})\s*G(?:SM)?\b", t)
    return dims, (g.group(1) if g else "")


def _dims_regex(dims):
    # Giữa các số quy cách OCR có thể đọc 'x', '*', '°', '+', '"'...: chấp nhận 1-2 ký tự bất kỳ không phải số
    sep = r"\s*(?:\([^)]{0,12}\))?\s*(?:mm)?\s*[^\d\s.,]{1,2}\s*"
    return r"(?<![\d.])" + sep.join(re.escape(d) for d in dims) + r"(?![\d])"


def _normalize_ocr_numbers(line):
    """'12, 000. 0000' -> '12,000.0000'; bỏ ngày dạng 2026-09-18 / 18/09/2026 để không lẫn vào số lượng."""
    prev = None
    while prev != line:  # chỉ nối nhóm nghìn khi phần trước là số có 1-3 chữ số (không nối '2508, 2500')
        prev = line
        line = re.sub(r"(?<![\d.,])(\d{1,3}(?:[.,]\d{3})*)\s*([.,])\s+(\d{3})(?!\d)", r"\1\2\3", line)
    line = re.sub(r"(?<![\d.,])(\d{1,3}(?:[.,]\d{3})+)([.,])\s+(\d+)", r"\1\2\3", line)
    return re.sub(r"(?<!\d)(20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}|\d{1,2}[-/.]\d{1,2}[-/.]20\d{2})(?!\d)", " ", line)


def _qty_price_from_numbers(nums, known_price):
    """Tìm (SL, đơn giá, độ tin cậy) trong các số của một dòng PO.
    3-2: có bộ SL x Giá = Thành tiền (thành tiền là số lớn nhất dòng); 1: thấy giá đã học, SL = số lớn nhất còn lại;
    0: không thấy giá, lấy giá đã học. Không tìm được thì SL = 0."""
    if not nums:
        return 0, known_price or 0, 0
    amt = max(nums)
    best = None
    for i, q in enumerate(nums):
        if q <= 0 or q >= amt:
            continue
        p = amt / q
        others = [n for j, n in enumerate(nums) if j != i and n != amt]
        seen = any(abs(n - p) <= max(0.01, p * 0.002) for n in others)
        near_known = bool(known_price) and abs(p - known_price) <= known_price * 0.02
        if not (seen or near_known):
            continue
        # đơn giá thật thường tròn (số nguyên / 2 số lẻ); số lượng đọc sai cho ra giá lẻ
        key = (abs(p - round(p, 2)) > 1e-6, -(seen + near_known), abs(p - (known_price or p)))
        if best is None or key < best[0]:
            best = (key, q, round(p, 2), 2 + (seen and near_known))
    if best:
        p = best[2]
        return best[1], (int(p) if float(p).is_integer() else p), best[3]
    if known_price:
        seen = [n for n in nums if abs(n - known_price) <= known_price * 0.02]
        rest = [n for n in nums if n not in seen]
        if seen and rest:
            return max(rest), seen[0], 1
        if rest:
            return max(rest), known_price, 0
    return 0, known_price or 0, 0


def _loose_values(tok):
    """Các giá trị có thể của một số trên PO scan (PO in số kiểu '1,200.00'), giá trị dễ đúng nhất đứng trước.
    '2,881,800,00' / '1,200.00' -> phần thập phân 2 chữ số; '120000' -> 1200 (OCR nuốt '.00') rồi mới 120000."""
    digits = re.sub(r"\D", "", tok)
    if re.search(r"[.,]\d{2}$", tok) and len(digits) > 2:
        v = int(digits[:-2]) + int(digits[-2:]) / 100
        return [int(v) if float(v).is_integer() else v]
    out = []
    if len(digits) >= 3 and digits.endswith("00"):
        out.append(int(digits[:-2]))
    v = parse_vn_number(tok)
    if v and v not in out:
        out.append(v)
    return out


def _loose_po_line(line, catalog_items, skip_spans=()):
    """Dòng PO scan mờ (kiểu Best): nhận mặt hàng theo chiều dài 'xxxxMM' rồi chọn bộ SL / giá / thành tiền khớp nhất.
    OCR hay đọc sai đường kính ('ø40*4' -> '£10%4') và nuốt '.00', nên không dựa vào phần quy cách đầu.
    Trả về (mặt hàng, SL, đơn giá) hoặc None."""
    m = re.search(r"(\d{3,4})\s*MM", line, re.I)
    if not m or not re.search(r"[OÔoô0]ng\s*gi", line, re.I):
        return None
    cands = [it for it in catalog_items if (_name_dims(it.get("name"))[0] or [""])[-1] == m.group(1)]
    if not cands:
        return None
    tail = list(line)
    for a_, b_ in skip_spans:
        tail[a_:b_] = " " * (b_ - a_)
    tail = "".join(tail)[m.end():]
    tail = re.sub(r"(?<!\d)[23]0\d{2}/\d{1,2}/\d{1,2}", " ", tail)  # ngày giao (năm có thể đọc sai 3036)
    tail = re.sub(r"[A-Za-z]+\d+", " ", tail)  # QS.../PRS.../PackingF001: mã, không phải số lượng
    toks = [t for t in (_loose_values(x) for x in re.findall(r"\d[\d.,]*\d|\d", tail)) if t][:4]
    best = None
    for it in cands:
        price = it.get("price") or 0
        if not price or not toks:
            continue
        is_price = [any(abs(v - price) <= price * 0.002 for v in vals) for vals in toks]
        found = None
        # 3: SL x giá đã học = thành tiền
        for i, qs in enumerate(toks):
            for q in qs:
                for j in range(i + 1, len(toks)):
                    if not found and not is_price[j] and any(abs(q * price - a) <= a * 0.002 for a in toks[j]):
                        found = (3, q)
        # 2: thành tiền chia hết cho giá đã học
        for j in range(1, len(toks)):
            if found or is_price[j]:
                continue
            for a in toks[j]:
                q = a / price
                if not found and q >= 1 and abs(q - round(q)) < 1e-6:
                    found = (2, int(round(q)))
        # 1: thấy đúng giá đã học, SL là số đứng ngay trước giá
        if not found:
            for j in range(1, len(toks)):
                if is_price[j]:
                    found = (1, toks[j - 1][0])
                    break
        if found and (best is None or found[0] > best[0]):
            best = (found[0], it, found[1], price)
    if not best:
        return None
    qty = best[2]
    return best[1], (int(qty) if float(qty).is_integer() else qty), best[3]


_ERP_PRICE = re.compile(r"(?<![\d.,])(\d[\d,]*\.\d{6})(?!\d)")
_ERP_QTY = re.compile(r"(?<![\d.,])(\d[\d,]*\.\d{4})(?!\d)")


def parse_erp_po_rows(text):
    """PO in từ ERP (VD Arizon), có lớp chữ hoặc đã OCR: mỗi dòng hàng có mã vật liệu, đơn giá 6 số lẻ, số lượng 4 số lẻ.
    Đọc theo từng cột nên không nhầm SL với giá. OCR có thể làm rơi đơn giá hoặc ĐVT: khi đó giá lấy theo mặt hàng đã học.
    Trả [{code, price (0 nếu thiếu), qty, desc}]; không có dòng nào khớp thì trả []."""
    rows = []
    t = _normalize_ocr_numbers(text or "")
    for line in t.splitlines():
        qm = _ERP_QTY.search(line)
        if not qm:
            continue
        head = line[:qm.start()]
        code = next((w for w in re.findall(r"[A-Za-z0-9][A-Za-z0-9\-]{7,}", head) if re.search(r"\d", w) and not re.fullmatch(r"20\d{2}-\d{2}-\d{2}", w)), "")
        if not code:
            continue
        pm = _ERP_PRICE.search(head)
        try:
            qty = float(qm.group(1).replace(",", ""))
            price = float(pm.group(1).replace(",", "")) if pm else 0.0
        except ValueError:
            continue
        if qty <= 0 or qty >= 5_000_000:
            continue
        desc = re.sub(r"20\d{2}-\d{2}-\d{2}", " ", line[qm.end():])
        desc = re.sub(r"^\s*(PCS|EA|PC|SET)\b", " ", desc)
        rows.append({"code": code, "price": price, "qty": qty, "desc": re.sub(r"\s+", " ", desc).strip()})
    return rows


_PCS_ROW = re.compile(
    r"(?P<code>(?<![A-Za-z0-9])\d[A-Z0-9]{9,}(?![A-Za-z0-9]))(?P<mid>.{0,220}?)(?P<qty>(?<![\d,.])\d[\d,]*)\s*(?P<unit>PCS|EA|PC|SET)\s+(?P<amt>\d[\d,]*\.\d{2})\s+(?P<date>\d{2}/\d{2}/\d{4})\s*(?P<price>\d[\d,]*\.\d{2,4})",
    re.S,
)


_KIND_CN = (("纸滑板", "SLIP"), ("滑板", "SLIP"), ("纸筒", "ONG"), ("纸管", "ONG"), ("纸护角", "NEP"), ("护角", "NEP"), ("纸箱", "THUNG"), ("纸盖", "NAP"))
_KIND_VI = (("ONG GIAY", "ONG"), ("SLIP", "SLIP"), ("THANH NEP", "NEP"), ("NEP GOC", "NEP"), ("NAP GIAY", "NAP"), ("THUNG", "THUNG"), ("KE GO", "KE"), ("KE GIAY", "KE"))


def desc_kind(text):
    """Loại hàng của một mô tả (chữ Hán hoặc tiếng Việt): ONG, SLIP, NEP, NAP, THUNG, KE hoặc ''."""
    t = str(text or "")
    for cn, k in _KIND_CN:
        if cn in t:
            return k
    u = strip_accents_upper(t)
    for vi, k in _KIND_VI:
        if vi in u:
            return k
    return ""


def desc_dims(text):
    """Ba kích thước đầu trong mô tả, bỏ ký hiệu Φ/外/内/H và chữ Hán: '纸筒/外Φ43.5X内Φ39.5XH290mm' -> ['43.5', '39.5', '290']."""
    t = re.sub(r"[φΦØ∅]|[\u4e00-\u9fff]|(?<=[Xx*])\s*H(?=\d)|^\s*H(?=\d)", " ", str(text or ""))
    t = re.sub(r"(?<=\d)\s*[Xx×]\s*(?=H?\d)", "x", t)
    t = re.sub(r"x\s*H(?=\d)", "x", t)
    dims, _g = _name_dims(t)
    return dims[:3]


def resolve_po_item(row, catalog, erp_catalog=None):
    """Tên và mã hàng cho một dòng PO (SL, mã liệu, mô tả chữ Hán...): thứ tự tin cậy
    1) danh mục khách theo mã liệu, nhưng chỉ khi kích thước trong mô tả không mâu thuẫn (mã học nhầm thì bỏ);
    2) danh mục ERP theo mã liệu ghi trong ngoặc tên hàng;
    3) danh mục khách theo loại hàng + kích thước;
    4) danh mục ERP theo loại hàng + kích thước.
    Trả {name, code, item, src}: item là mục danh mục khách (có kg, SL/kiện) hoặc None; src khach/erp/''."""
    code = str(row.get("code") or "").strip()
    desc = str(row.get("desc") or row.get("name") or "")
    dims, kind = desc_dims(desc), desc_kind(desc)
    cat = list(catalog or [])
    erp = list(erp_catalog or [])

    def consistent(name):
        d2 = _name_dims(name)[0][:3]
        k2 = desc_kind(name)
        return (not dims or not d2 or [float(x) for x in d2] == [float(x) for x in dims]) and (not kind or not k2 or kind == k2)

    if code:
        it = next((x for x in cat if str(x.get("code") or "") == code and consistent(x.get("name", ""))), None)
        if it:
            return {"name": it["name"], "code": code, "item": it, "src": "khach"}
        e = next((x for x in erp if f"({code})" in str(x.get("ten_sp") or "").replace(" ", "")), None)
        if e:
            return {"name": re.sub(r"\s+", " ", e["ten_sp"]).strip(), "code": code, "item": None, "src": "erp"}
    if dims:
        want = [float(x) for x in dims]
        for src_name, lst in (("khach", cat), ("erp", erp)):
            for x in lst:
                nm = x.get("name") if src_name == "khach" else x.get("ten_sp")
                d2 = _name_dims(nm or "")[0][:3]
                if len(d2) == len(want) and [float(v) for v in d2] == want and (not kind or desc_kind(nm) in ("", kind)):
                    if src_name == "khach":
                        return {"name": x["name"], "code": code or str(x.get("code") or ""), "item": x, "src": "khach"}
                    return {"name": re.sub(r"\s+", " ", nm).strip(), "code": code, "item": None, "src": "erp"}
    return {"name": "", "code": code, "item": None, "src": ""}


_DATED_ROW = re.compile(
    r"(?P<code>(?<![A-Za-z0-9.])\d{6,12}(?![A-Za-z0-9]))(?P<desc>[^\n]{0,160}?)\s+(?P<date>20\d{2}-\d{2}-\d{2})\s+(?P<qty>\d[\d,]*(?:\.\d+)?)\s+(?P<unit>PCS?|EA|SET|PC|Chiếc|chiếc|Cái|cái)\s+"
    r"(?P<price>\d[\d,]*(?:\.\d+)?)\s+(?P<amt>\d[\d,]*(?:\.\d+)?)",
)


def parse_dated_unit_rows(text):
    """PO kiểu 'STT | Mã liệu | Mô tả | Ngày giao (yyyy-mm-dd) | SL | ĐVT | Đơn giá | Thành tiền' (VD Richsound).
    Mã liệu là số dài, SL đứng sau ngày giao và trước đơn vị: không lẫn mã với số lượng. Chỉ nhận dòng có SL x đơn giá = thành tiền.
    Trả [{code, desc, qty, price, ship}]."""
    rows = []
    for m in _DATED_ROW.finditer(text or ""):
        try:
            qty, price, amt = (float(m.group(k).replace(",", "")) for k in ("qty", "price", "amt"))
        except ValueError:
            continue
        if qty <= 0 or price <= 0 or abs(qty * price - amt) > max(1.0, amt * 1e-6):
            continue
        d = m.group("date")
        rows.append({"code": m.group("code"), "desc": re.sub(r"\s+", " ", m.group("desc")).strip(), "qty": qty, "price": price,
                     "ship": f"{d[8:10]}/{d[5:7]}/{d[:4]}"})
    return rows


_PO_LABEL_RE = re.compile(r"(?:mã\s*PO|PO\s*(?:No|number)|订单编号|采购订单编号)\s*[:：]?\s*(\d{7,14})", re.I)


_XL_HEADERS = {
    "name": ("TEN HANG", "TEN SAN PHAM", "HANG HOA", "DESCRIPTION OF GOODS", "PRODUCT"),
    "spec": ("QUY CACH", "THONG SO", "MO TA", "DESCRIPTION", "SPECIFICATION"),
    "code": ("MA HANG", "MA LIEU", "MA SP", "ITEM CODE", "PART NO", "CODE"),
    "unit": ("DON VI", "DVT", "UNIT"),
    "qty": ("SO LUONG", "QUANTITY", "QTY"),
    "price": ("DON GIA", "UNIT PRICE", "PRICE"),
    "amount": ("THANH TIEN", "AMOUNT", "TOTAL"),
}


def _xl_number(v, formula=None):
    """Số trong ô Excel: số thật, chuỗi '1,200', hoặc công thức cộng trừ đơn giản chưa có giá trị lưu sẵn (=992+2504)."""
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    if isinstance(v, str) and v.strip():
        t = v.strip().replace(",", "")
        try:
            return float(t)
        except ValueError:
            pass
    if v is None and isinstance(formula, str) and re.fullmatch(r"=[\d.+\-*/() ]+", formula):
        try:
            return float(eval(formula[1:], {"__builtins__": {}}, {}))  # noqa: S307 - chỉ gồm số và + - * / ( ), đã kiểm bằng regex
        except Exception:
            return None
    return None


def parse_excel_table_po(path):
    """PO Excel dạng bảng (hàng tiêu đề: tên hàng / quy cách / số lượng / đơn giá / thành tiền, ở sheet nào cũng được). Tìm hàng tiêu đề theo chữ,
    đọc từng dòng hàng đến dòng 'Tổng'. Bỏ dòng không có số lượng (dòng mẫu trống). Trả [{name, spec, code, unit, qty, price, amount, sheet, row}]."""
    try:
        wbv = openpyxl.load_workbook(path, data_only=True)
        wbf = openpyxl.load_workbook(path, data_only=False)
    except Exception:
        return []
    out = []
    for ws in wbv.worksheets:
        wf = wbf[ws.title]
        head, cols = None, {}
        for r in range(1, min(ws.max_row, 60) + 1):
            found = {}
            for c in range(1, min(ws.max_column, 26) + 1):
                t = strip_accents_upper(str(ws.cell(r, c).value or "")).replace("\n", " ")
                for key in ("amount", "price", "qty", "code", "unit", "spec", "name"):  # 'đơn giá' phải xét trước 'đơn vị'
                    if key not in found and any(k in t for k in _XL_HEADERS[key]) and not (key == "unit" and "DON GIA" in t):
                        found[key] = c
                        break
            if {"qty", "price"} <= set(found) and ("name" in found or "spec" in found):
                head, cols = r, found
                break
        if head is None:
            continue
        for r in range(head + 1, ws.max_row + 1):
            first = strip_accents_upper(" ".join(str(ws.cell(r, c).value or "") for c in range(1, 4)))
            if re.match(r"\s*(TONG|TOTAL|THUE|VAT)", first):
                break
            def num(key):
                c = cols.get(key)
                return _xl_number(ws.cell(r, c).value, wf.cell(r, c).value) if c else None
            qty, price = num("qty"), num("price")
            if not qty or qty <= 0 or not price or price <= 0:
                continue
            txt = lambda key: re.sub(r"\s+", " ", str(ws.cell(r, cols[key]).value or "")).strip() if key in cols else ""
            out.append({"name": txt("name"), "spec": txt("spec"), "code": txt("code"), "unit": txt("unit"), "qty": qty, "price": price,
                        "amount": num("amount"), "sheet": ws.title, "row": r})
        if out:
            break
    return out


def match_po_item(row, catalog):
    """Mặt hàng đã học ứng với một dòng PO: theo mã khách ghi trong ngoặc '(44A020101.0319)', rồi theo mã ở cột mã, rồi theo loại hàng + kích thước.
    Trả mục danh mục hoặc None."""
    text = f"{row.get('name', '')} {row.get('spec', '')}"
    cat = list(catalog or [])
    m = re.search(r"\(\s*([0-9A-Z][0-9A-Z.]{5,})\s*\)", text)
    if m:
        code = m.group(1)
        hit = next((it for it in cat if f"({code})" in str(it.get("name") or "").replace(" ", "")), None) or next((it for it in cat if str(it.get("code") or "") == code), None)
        if hit:
            return hit
    code = str(row.get("code") or "").strip()
    if code:
        hit = next((it for it in cat if str(it.get("code") or "") == code), None)
        if hit:
            return hit
    dims, _g = _name_dims(text)
    kind = re.split(r"\d", strip_accents_upper(f"{row.get('name', '')} {row.get('spec', '')}"), maxsplit=1)[0]
    kind = re.sub(r"[^A-Z ]", " ", kind).split()
    kind = " ".join(kind[:2]) if kind else ""
    if dims:
        for it in cat:
            d2, _ = _name_dims(it.get("name", ""))
            k2 = re.sub(r"[^A-Z ]", " ", re.split(r"\d", strip_accents_upper(it.get("name", "")), maxsplit=1)[0]).split()
            if d2 == dims and (not kind or " ".join(k2[:2]) == kind):
                return it
    return None


def lines_from_excel_table(rows, po_no, profile, catalog, data_store=None, tare_val=0.0):
    """Dòng hàng từ parse_excel_table_po: dòng khớp mặt hàng đã học (đầy đủ kg, SL/kiện); dòng lạ vẫn giữ theo chữ trên PO (trạng thái 'suy ra') để người dùng điền."""
    erp_rows = []
    for r in rows:
        it = match_po_item(r, catalog)
        erp_rows.append({"code": (it or {}).get("code") or "", "desc": (it or {}).get("name") or re.sub(r"\s+", " ", f"{r['name']} {r['spec']}").strip(),
                         "qty": r["qty"], "price": r["price"], "_matched": bool(it)})
    lines = lines_from_erp_rows(erp_rows, po_no, profile, catalog, data_store=data_store, tare_val=tare_val)
    for ln, r, e in zip(lines, rows, erp_rows):
        if not e["_matched"]:
            ln["read"], ln["read_note"] = "suy_ra", "Mặt hàng chưa có trong danh mục khách: kiểm tra mã, kg, SL/kiện"
    return lines


def _po_pattern_hits(prof, text, po_no):
    """Số PO đọc được có do mẫu nhận dạng của khách tìm ra không (mẫu hỏng hay không khớp thì số này chỉ là đoán)."""
    pat = (prof or {}).get("po_pattern") or ""
    if not pat or not po_no:
        return False
    try:
        flat = re.sub(r"(?<=\d) (?=\d)", "", text or "")
        return any(re.sub(r"\s+", "", m.group(0)) == po_no for m in re.finditer(pat, flat, re.I))
    except re.error:
        return False


def find_po_after_label(text):
    """Số PO ngay sau nhãn 'mã PO' / '采购订单编号' (PO của khách chưa có mẫu nhận dạng số PO)."""
    flat = re.sub(r"[ \t]+", " ", text or "")
    m = _PO_LABEL_RE.search(flat) or re.search(r"(?:mã\s*PO|订单编号)[^\d\n]{0,30}(\d{7,14})", flat, re.I)
    return m.group(1) if m else ""


def parse_pcs_note_rows(text):
    """PO kiểu 'Mã SP | Mô tả | SL PCS | Thành tiền | Ngày giao + Đơn giá' (VD Quang Ích). Mỗi dòng: mã, SL, thành tiền, ngày giao, đơn giá.
    Chỉ nhận dòng có SL x đơn giá = thành tiền. Trả [{code, qty, price, desc, ship}]."""
    rows = []
    for m in _PCS_ROW.finditer(text or ""):
        try:
            qty, amt, price = (float(m.group(k).replace(",", "")) for k in ("qty", "amt", "price"))
        except ValueError:
            continue
        if qty <= 0 or price <= 0 or abs(qty * price - amt) > 1:
            continue
        rows.append({"code": m.group("code"), "qty": qty, "price": price, "ship": m.group("date"),
                     "desc": re.sub(r"\s+", " ", re.sub(r"[^\x20-\x7E\u00C0-\u1EF9]", " ", m.group("mid"))).strip()})
    return rows


def erp_rows_repaired(text, catalog_items):
    """parse_erp_po_rows + sửa dòng OCR làm rơi số lượng: dòng có mã hàng đã học mà mất SL thì tính lại từ tổng SL / tổng tiền của PO
    (một ẩn: lấy từ tổng tiền; hai ẩn khác giá: giải hệ hai phương trình). Không giải được thì để SL = 0 cho người dùng điền."""
    rows = parse_erp_po_rows(text)
    if not rows:  # không phải PO ERP kiểu này: không "sửa" gì cả
        return rows
    have = {r["code"] for r in rows}
    codes = {str(it.get("code") or "").strip(): it for it in catalog_items if it.get("code")}
    order = []
    for line in _normalize_ocr_numbers(text or "").splitlines():
        m = next((c for c in re.findall(r"\d{10,}", line) if c in codes), None)
        if m and m not in have and not _ERP_QTY.search(line):
            order.append(m)
    if not order:
        return rows
    flat = _normalize_ocr_numbers(text or "").replace(" ", "")
    tq = re.search(r"TotalQuantity/?([\d,]+\.\d{2,4})", flat)
    ta = re.search(r"TotalAmount/?([\d,]+\.\d{2,4})", flat)
    tq = float(tq.group(1).replace(",", "")) if tq else 0.0
    ta = float(ta.group(1).replace(",", "")) if ta else 0.0
    known_q = sum(r["qty"] for r in rows)
    known_a = sum(r["qty"] * (r["price"] or float((codes.get(r["code"]) or {}).get("price") or 0)) for r in rows)
    prices = [float(codes[c].get("price") or 0) for c in order]
    qtys = [0.0] * len(order)
    if len(order) == 1 and prices[0] and ta:
        qtys[0] = round((ta - known_a) / prices[0])
    elif len(order) == 2 and tq and ta and prices[0] != prices[1] and all(prices):
        q_sum, a_sum = tq - known_q, ta - known_a
        q2 = (a_sum - prices[0] * q_sum) / (prices[1] - prices[0])
        q1 = q_sum - q2
        if abs(q1 - round(q1)) < 1e-6 and abs(q2 - round(q2)) < 1e-6 and q1 > 0 and q2 > 0:
            qtys = [round(q1), round(q2)]
    for c, q, p in zip(order, qtys, prices):
        rows.append({"code": c, "price": p, "qty": q, "desc": "", "repaired": True})
    # giữ thứ tự dòng như trên PO (mã sắp theo vị trí xuất hiện trong văn bản)
    pos = {}
    for i, line in enumerate(_normalize_ocr_numbers(text or "").splitlines()):
        for c in re.findall(r"\d{10,}", line):
            pos.setdefault(c, i)
    rows.sort(key=lambda r: pos.get(r["code"], 10**6))
    return rows


def pdf_text_head(path, pages=2):
    """Chữ của vài trang đầu PDF (chỉ lớp chữ có sẵn, không OCR); '' nếu là ảnh scan."""
    try:
        r = pypdf.PdfReader(path)
        return "\n".join((r.pages[i].extract_text() or "") for i in range(min(pages, len(r.pages))))
    except Exception:
        return ""


def classify_dropped(path):
    """Nhận biết file người dùng thả vào hồ sơ: (loại, số). Loại: PXK, HD (hóa đơn Bkav), IV (invoice), PO, DSH, TK (tờ khai),
    XLS_IV (invoice Excel), XLS_DCCN, XLS (Excel khác), '' (không rõ). Số = số phiếu xuất kho nếu đọc được (bỏ số 0 đầu).
    PDF Bkav có lớp chữ thì đọc nội dung; file scan chỉ nhận theo tên."""
    name = os.path.basename(path)
    base, ext = os.path.splitext(name.lower())
    pdfish = ext in (".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff")
    if base.startswith("dsh"):
        return "DSH", ""
    m = re.match(r"0*(\d{3,9})[_ -]+\d{12}", base)
    if m:
        return "TK", m.group(1)  # tờ khai đặt tên '<số PXK>_<số tờ khai>'
    if re.search(r"(?<!\d)\d{12}(?!\d)", base) or "tokhai" in base.replace("_", "").replace(" ", ""):
        return "TK", ""
    if pdfish and ext == ".pdf":
        head = strip_accents_upper(pdf_text_head(path))
        if "PHIEU XUAT KHO" in head:
            m = re.search(r"(?:PXK|SO|NO)\D{0,8}(\d{5,10})", head) or re.search(r"(?<!\d)(\d{6,10})(?!\d)", head)
            return "PXK", (m.group(1).lstrip("0") or "0") if m else ""
        if "HOA DON GIA TRI GIA TANG" in head or "HOA DON" in head and "KY HIEU" in head:
            return "HD", ""
    if pdfish:
        if re.search(r"c\d{2}n[a-z]{2}", base) or re.match(r"pxk", base):
            m = re.search(r"(?<!\d)0*(\d{2,9})(?!\d)", base)
            return "PXK", m.group(1) if m else ""
        if re.search(r"c\d{2}t[a-z]{2}", base) or re.match(r"h[đd]\s*\d", base):
            return "HD", ""
        if re.match(r"(iv|inv|invoice)", base):
            m = re.search(r"(?<!\d)0*(\d{2,9})(?!\d)", base)
            return "IV", m.group(1) if m else ""
        if re.match(r"po", base):
            return "PO", ""
    if ext in (".xlsx", ".xlsm", ".xls"):
        if re.match(r"(iv|inv|invoice)", base):
            return "XLS_IV", ""
        if base.startswith("dccn"):
            return "XLS_DCCN", ""
        return "XLS", ""
    return "", ""


def plan_add_files(customs_root, cust_name, day, paths, pxk_no=""):
    """Kế hoạch thêm file vào hồ sơ <Khách>/<yyyy>_Thang_<mm>/<ngày>: file do phần mềm tạo/Excel/PO gốc vào DO_PHAN_MEM_TAO,
    PDF Bkav, scan, tờ khai, dsh để bên ngoài. PDF Bkav đặt lại tên theo số phiếu xuất kho: 'PXK 247', 'HĐ 247', 'Invoice 247';
    tờ khai giữ nguyên tên. Số phiếu xuất kho lấy từ ô nhập, hoặc file PXK, hoặc tên tờ khai '<số>_<số tờ khai>', hoặc file đã có trong thư mục.
    Trả (số PXK dùng, [{src, kind, new_name, area ('ngoai'|'tao'), dst, note}])."""
    folder = os.path.join(customs_root, cust_name, f"{day[:4]}_Thang_{day[5:7]}", day)
    cls = [(p, *classify_dropped(p)) for p in paths]
    no = str(pxk_no or "").strip().lstrip("0")
    if not no:
        no = next((n for _p, k, n in cls if k == "PXK" and n), "")
    if not no:
        no = next((n for _p, k, n in cls if k == "TK" and n), "")
    if not no:
        for n in (os.listdir(folder) if os.path.isdir(folder) else []):
            m = re.match(r"(?:PXK|H[ĐD]|Invoice)\s+(\d+)(?:_\d+)?\.pdf$", n, re.I) or re.match(r"0*(\d{3,9})_\d{12}", n)
            if m:
                no = m.group(1)
                break
    out = []
    for p, kind, _n in cls:
        name = os.path.basename(p)
        ext = os.path.splitext(name)[1].lower()
        area, new, note = "ngoai", name, ""
        if kind in ("PXK", "HD", "IV") and ext == ".pdf":
            label = {"PXK": "PXK", "HD": "HĐ", "IV": "Invoice"}[kind]
            if no:
                new = f"{label} {no}.pdf"
            else:
                note = "Chưa biết số phiếu xuất kho: nhập số vào ô trên để đặt tên"
        elif kind in ("PXK", "HD", "IV"):
            new = f"{ {'PXK': 'PXK', 'HD': 'HĐ', 'IV': 'Invoice'}[kind] } {no}{ext}" if no else name
        elif kind == "PO":
            area, new = "tao", "PO_goc_" + name
        elif kind == "XLS_IV":
            area, new = "tao", "invoice_" + name
        elif kind == "XLS_DCCN":
            area, new = "tao", "DoiChieuCongNo_" + name
        elif kind == "XLS":
            area = "tao"
        out.append({"src": p, "kind": kind, "new_name": new, "area": area,
                    "dst": os.path.join(folder, GENERATED_DIR if area == "tao" else "", new), "note": note})
    return no, out


def apply_add_files(plan):
    """Sao chép các file theo kế hoạch (không ghi đè: trùng tên thì thêm _2). Trả danh sách đường dẫn đích."""
    done = []
    for it in plan:
        dst = it["dst"]
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        stem, ext = os.path.splitext(dst)
        n = 2
        while os.path.exists(dst):
            dst = f"{stem}_{n}{ext}"
            n += 1
        shutil.copy2(it["src"], dst)
        done.append(dst)
    return done


READ_LABELS = {"ok": "✅ Đọc đủ", "suy_ra": "🟡 Suy ra, kiểm tra", "loi": "❌ Chưa đọc được", "tay": "✍ Nhập tay"}


def read_report(lines, check=""):
    """Tóm tắt kết quả đọc PO theo từng dòng: {ok, suy_ra, loi, total, bad_rows, text}. Dòng chưa đọc được nằm sẵn trong bảng (tô đỏ) để nhập tay."""
    n = {k: sum(1 for x in lines if x.get("read") == k) for k in ("ok", "suy_ra", "loi")}
    total = len(lines)
    bad = [i for i, x in enumerate(lines, 1) if x.get("read") == "loi"]
    warn = [i for i, x in enumerate(lines, 1) if x.get("read") == "suy_ra"]
    if not bad and not warn:
        text = f"✅ Đã đọc đủ {total}/{total} dòng."
    else:
        text = f"Đọc được {total - len(bad)}/{total} dòng."
        if bad:
            text += f" ❌ Chưa đọc được dòng {', '.join(map(str, bad))}: đã thêm sẵn ở bảng, hãy nhập tay."
        if warn:
            text += f" 🟡 Dòng {', '.join(map(str, warn))} phải suy ra từ ô khác: hãy so với PO."
    if check:
        text += " " + check
    return {**n, "total": total, "bad_rows": bad, "warn_rows": warn, "text": text}


_DATE_TOK = re.compile(r"20\d{2}-\d{2}-\d{2}|\d{1,2}/\d{1,2}/20\d{2}")
_NUM_TOK = re.compile(r"(?<![\w.,])\d[\d,]*(?:\.\d+)?(?![\w])")


def line_numbers(text):
    """Các số trong một dòng PO theo thứ tự xuất hiện (ngày yyyy-mm-dd hay dd/mm/yyyy tính là một mục, không tách thành nhiều số).
    Trả [chuỗi số đúng như in trên PO]."""
    flat = _DATE_TOK.sub(" ", str(text or ""))
    return [m.group(0).rstrip(",") for m in _NUM_TOK.finditer(flat)]


def source_line_for(raw_text, item):
    """Dòng chữ của PO mà một dòng hàng được đọc ra (tìm theo mã hàng, rồi theo số lượng + đơn giá). '' nếu không tìm thấy."""
    lines = [ln.strip() for ln in str(raw_text or "").splitlines() if ln.strip()]
    code = str(item.get("ma_sp") or "").strip()
    if len(code) >= 4:
        for ln in lines:
            if code in ln and len(line_numbers(ln)) >= 3:
                return ln[:400]
    qty, price = item.get("qty"), item.get("price")
    if qty and price:
        fq, fp = {f"{qty:,}", str(qty)} if isinstance(qty, int) else {str(qty)}, {f"{price:,}", str(price)} if isinstance(price, int) else {str(price)}
        for ln in lines:
            nums = line_numbers(ln)
            if fq & set(nums) and fp & set(nums):
                return ln[:400]
    return ""


def attach_sources(items, raw_text):
    """Gắn dòng PO gốc (`src`) vào từng dòng hàng chưa có, để người dùng chọn lại số đúng khi máy đọc sai."""
    for it in items:
        if not it.get("src"):
            src = source_line_for(raw_text, it)
            if src:
                it["src"] = src
    return items


def apply_read_rules(items, rules):
    """Áp quy tắc vị trí số đã học (SL, đơn giá tính từ cuối dòng) cho dòng có đúng số lượng số như lúc học. Chỉ nhận khi SL x đơn giá = thành tiền (nếu có số thành tiền).
    Trả số dòng đã sửa theo quy tắc."""
    if not rules or "qty" not in rules or "price" not in rules:
        return 0
    n_fixed = 0
    for it in items:
        if it.get("read") == "tay" or not it.get("src"):
            continue
        nums = line_numbers(it["src"])
        if rules.get("n") and len(nums) != rules["n"]:
            continue
        try:
            qty = float(nums[rules["qty"]].replace(",", ""))
            price = float(nums[rules["price"]].replace(",", ""))
            amt_i = rules.get("amount")
            if amt_i is not None and abs(qty * price - float(nums[amt_i].replace(",", ""))) > max(1.0, price * 1e-3):
                continue
        except (IndexError, ValueError):
            continue
        if qty <= 0 or price <= 0:
            continue
        qty, price = (int(qty) if qty == int(qty) else qty), (int(price) if price == int(price) else price)
        if (it.get("qty"), it.get("price")) != (qty, price):
            it["qty"], it["price"], it["amount"] = qty, price, round(qty * price)
            n_fixed += 1
        it["read"], it["read_note"] = "ok", "Đọc theo quy tắc đã học cho khách này"
    return n_fixed


def mark_read(items, catalog=None):
    """Gắn trạng thái đọc cho dòng chưa có (mọi khách): ok = có SL, đơn giá và nhận ra mặt hàng trong danh mục; suy_ra = mặt hàng/đơn giá chưa chắc;
    loi = thiếu số lượng. Dòng đã có trạng thái (đọc theo ô, nhập tay) giữ nguyên."""
    known = {str(c.get("code") or "") for c in (catalog or []) if c.get("code")} | {c.get("name") for c in (catalog or [])}
    for it in items:
        if it.get("read"):
            continue
        qty, price = float(it.get("qty") or 0), float(it.get("price") or 0)
        if qty <= 0:
            it["read"], it["read_note"] = "loi", "Chưa có số lượng"
        elif price <= 0:
            it["read"], it["read_note"] = "suy_ra", "Chưa có đơn giá"
        elif known and (it.get("ma_sp") not in known and it.get("ten_sp") not in known):
            it["read"], it["read_note"] = "suy_ra", "Mặt hàng chưa có trong danh mục của khách"
        else:
            it["read"], it["read_note"] = "ok", ""
    return items


def lines_from_able_scan(rows, prof, catalog, store, tare_val=0.0):
    """Dòng hàng từ po_scan.read_able_pdf: dòng đọc được dựng như dòng PO thường; dòng chưa đọc được thành dòng trống để nhập tay.
    Mỗi dòng mang read (ok/suy_ra/loi), read_note và ref (mã tham chiếu cột ghi chú của PO)."""
    lines = []
    for r in rows:
        if r["read"] == "loi":
            lines.append({"stt": len(lines) + 1, "po": r.get("po", ""), "hs": (prof.get("customs") or {}).get("hs", "") or "48229090", "ma_sp": "", "ten_sp": "", "ten_hq": "",
                          "unit": prof.get("unit", "cái"), "qty": 0, "price": 0, "amount": 0, "div": 0, "kg": 0, "kien": 0, "net": 0.0, "gross": 0.0,
                          "tare": tare_val, "read": "loi", "read_note": r["read_note"], "ref": r.get("ref", ""), "page": r.get("page", 0), "box": r.get("box")})
            continue
        one_row = {"code": r["code"], "desc": r["name"], "qty": r["qty"], "price": r["price"]}
        if "_known" in r:
            one_row["_known"] = r["_known"]
        one = lines_from_erp_rows([one_row], r.get("po", ""), prof, catalog, data_store=store, tare_val=tare_val)[0]
        one.update({"stt": len(lines) + 1, "read": r["read"], "read_note": r["read_note"], "ref": r.get("ref", ""), "page": r.get("page", 0), "box": r.get("box")})
        lines.append(one)
    return lines


def lot_search_items(store, customer, query, limit=60):
    """Tra mặt hàng của khách để thêm dòng: gõ mã, tên, quy cách (38 x 5 x 467, 38*5*467) hoặc gam (250g). Mọi từ gõ vào đều phải có trong mã/tên.
    Trả [{ma_sp, ten_sp, price, unit, div, kg, hs}] gộp danh mục khách và data tổng, không trùng."""
    def norm(t):
        t = strip_accents_upper(str(t or "")).lower()
        t = re.sub(r"(?<=\d)\s*[x×*]\s*(?=\d)", "*", t)  # 38 x 5 x 467 -> 38*5*467
        t = re.sub(r"(?<=\d)\s+(?=g\b)", "", t)  # '250 g' -> '250g'
        return t.replace(",", ".")
    toks = [x for x in norm(query).split() if x]
    seen, out = set(), []
    cat = list(store.items_for_customer(customer) or [])
    for it in cat:
        mem = store.get_item_norm(it.get("name")) or {}
        out_item = {"ma_sp": str(it.get("code") or ""), "ten_sp": it.get("name", ""), "price": it.get("price", 0), "unit": it.get("unit", ""),
                    "div": mem.get("div") or it.get("div", 0), "kg": mem.get("kg") or it.get("kg", 0), "hs": mem.get("hs") or it.get("hs", "")}
        hay = norm(out_item["ma_sp"] + " " + out_item["ten_sp"])
        if all(t in hay for t in toks):
            key = (out_item["ma_sp"], out_item["ten_sp"])
            if key not in seen:
                seen.add(key)
                out.append(out_item)
    try:
        for x in store.dt_items_for(customer):
            name = x.get("ten") or ""
            hay = norm(str(x.get("ma_hang") or "") + " " + name + " " + str(x.get("ma_kh") or ""))
            key = (str(x.get("ma_kh") or x.get("ma_hang") or ""), name)
            if name and all(t in hay for t in toks) and key not in seen and not any(o["ten_sp"] == name for o in out):
                seen.add(key)
                out.append({"ma_sp": key[0], "ten_sp": name, "price": 0, "unit": (PROFILES.get(customer) or {}).get("unit", ""), "div": x.get("kien") or 0,
                            "kg": x.get("kg") or 0, "hs": x.get("hs") or ""})
    except Exception:
        pass
    return out[:limit]


def lot_item_from_catalog(store, customer, hit, qty, po="", tare_text="1.0"):
    """Dòng hàng mới từ một kết quả tra mặt hàng + số lượng nhập."""
    prof = PROFILES[customer]
    vals = {"po": po, "ma_sp": hit.get("ma_sp", ""), "ten_sp": hit.get("ten_sp", ""), "hs": hit.get("hs") or "48229090", "unit": hit.get("unit") or prof.get("unit", "cái"),
            "qty": qty, "price": hit.get("price") or 0, "div": hit.get("div") or 0, "kg": hit.get("kg") or 0}
    return lot_item_from_values(store, customer, vals, tare_text)


def is_able(prof):
    """Khách Able (nhận theo tên công ty): PO chữ Hán, mã hàng = quy cách + gam (VD 38*5*460*250g), bản in/không in."""
    return (prof or {}).get("poStyle") == "able" or bool(re.search(r"\bABLE\b", str((prof or {}).get("name") or "").upper()))


def parse_able_po_rows(text, catalog_items):
    """PO Able: mỗi dòng có tên (gam: 250g), quy cách (38*5*460), SL, đơn giá, thành tiền, mã tham chiếu 2026-2350-020.
    Chỉ cần gam + quy cách + SL: tra mã Able theo 'phi*dày*dài*gam'; có chữ 印刷 (in) thì lấy mã 'in', không có thì mã '-ko-in' nếu có.
    Trả [{code, desc, qty, price, ref}] (price 0 nếu không đọc được: lấy giá của danh mục)."""
    cat = {str(it.get("code") or ""): it for it in catalog_items if it.get("code")}
    rows = []
    has_cjk = bool(re.search(r"[\u4e00-\u9fff]", text or ""))
    spec_re = re.compile(r"(?<![\d.])(\d{2})\s*[*xX×]\s*(\d{1,2})\s*[*xX×]\s*(\d{3})(?!\d)")
    for line in (text or "").splitlines():
        m = spec_re.search(line)
        if not m:
            continue
        d, t, ln = m.groups()
        wm = re.search(r"(?<![\d.])(\d{2,3}(?:[.,]\d)?)\s*g\b", line[:m.start()] + " " + line[m.end():], re.I)
        if not wm:
            continue
        w = wm.group(1).replace(",", ".")
        tail = line[m.end():]
        nums = [float(x.replace(",", "")) for x in re.findall(r"(?<![\d-])\d[\d,]*(?:\.\d+)?(?![\d-])", tail) if x.replace(",", "") not in ("",)]
        qty = price = 0.0
        for i, q in enumerate(nums):
            if q == int(q) and 1 <= q < 5_000_000 and i + 2 < len(nums) + 1:
                rest = nums[i + 1:i + 3]
                if len(rest) == 2 and abs(q * rest[0] - rest[1]) < 1.5:
                    qty, price = q, rest[0]
                    break
        if not qty:  # không đối chiếu được giá: nhận số nguyên đầu tiên sau quy cách là SL
            qty = next((q for q in nums if q == int(q) and 1 <= q < 5_000_000), 0.0)
        if not qty:
            continue
        printed = bool(re.search(r"印刷|\bin\b", line, re.I)) if has_cjk else True  # OCR không có chữ Hán: coi là bản in (loại phổ biến)
        base = f"{d}*{t}*{ln}*{w}g"
        order = [base, base + "-ko-in"] if printed else [base + "-ko-in", base]
        code = next((c for c in order if c in cat), "")
        if not code:  # quy cách dày khác (VD 28*2*305 trong PO, 28*5*305 trong danh mục): khớp theo phi, dài, gam
            code = next((c for c in cat if re.fullmatch(rf"{d}\*\d+\*{ln}\*{re.escape(w)}g(?:-ko-in)?", c)), "")
        ref = re.search(r"20\d{2}-\d{3,4}-\d{3}", line)
        rows.append({"code": code or base, "desc": cat.get(code, {}).get("name") or base, "qty": qty, "price": price, "ref": ref.group(0) if ref else ""})
    return rows


def lines_from_erp_rows(rows, po_no, profile, catalog_items, data_store=None, tare_val=0.0):
    """Dòng hàng từ parse_erp_po_rows: mặt hàng đã học (theo mã) lấy tên, kg, định mức đã nhớ; mặt hàng mới lấy tên/giá theo PO
    (kg, định mức để trống cho người dùng điền ở Bước 3, rồi được nhớ cho lần sau)."""
    by_code = {str(it.get("code") or "").strip(): it for it in catalog_items if it.get("code")}
    lines = []
    for r in rows:
        known = r["_known"] if "_known" in r else (by_code.get(r["code"]) or {})
        if not known and "_known" not in r:  # mã đọc hỏng: nhận mặt hàng theo quy cách trong mô tả (3 số cuối: phi x dày x cao)
            nums = re.findall(r"\d+(?:\.\d+)?", r["desc"])
            known = next((it for it in catalog_items if len(nums) >= 3 and _name_dims(it.get("name"))[0] == nums[-3:]), {}) if nums else {}
        name = known.get("name") or r["desc"] or r["code"]
        code = known.get("code") or r["code"]
        mem = data_store.get_item_norm(name) if data_store else None
        div = (mem or {}).get("div") or known.get("div") or profile.get("defaultDiv") or 0
        kg = (mem or {}).get("kg") or known.get("kg") or 0
        qty = int(round(r["qty"])) if abs(r["qty"] - round(r["qty"])) < 1e-9 else r["qty"]
        rp = r["price"] or float(known.get("price") or 0)
        price = int(round(rp)) if abs(rp - round(rp)) < 1e-9 else rp
        net = round_half_up(qty * kg, 2) if kg > 0 else 0.0
        lines.append({
            "stt": len(lines) + 1, "po": po_no, "hs": (mem or {}).get("hs") or known.get("hs", "") or (profile.get("customs") or {}).get("hs", ""),
            "ma_sp": code, "ten_sp": name, "ten_hq": known.get("ten_hq") or name,
            "unit": known.get("unit") or profile.get("unit", "cái"), "qty": qty, "price": price, "amount": round(qty * price),
            "div": div, "kg": kg, "kien": math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0, "net": net,
            "gross": round_half_up(net + tare_val, 2) if net > 0 else 0.0, "tare": tare_val,
            **({"shipDate": r["ship"]} if r.get("ship") else {}),
        })
    return lines


def parse_generic_po_text(text, profile, catalog_items, data_store=None, tare_val=0.0):
    """Đọc PO của khách mới: số PO theo mẫu đã học, dòng hàng = dòng có mã / tên / quy cách hàng đã học."""
    pat = profile.get("po_pattern") or ""
    po_no = ""
    if pat:
        # OCR hay chèn dấu cách giữa các chữ số ('2026091 10005'); số PO nằm gần chữ 'PO' được ưu tiên
        flat_txt = re.sub(r"(?<=\d) (?=\d)", "", text or "")
        try:
            found = list(re.finditer(pat, flat_txt, re.I))
        except re.error:
            found = []
        if found:
            near_po = [m for m in found if re.search(r"P\.?\s?O\b|Purchase|đơn\s*(?:mua|đặt)|合同|订单", flat_txt[max(0, m.start() - 40):m.start()], re.I)]
            po_no = re.sub(r"\s+", "", (near_po or found)[0].group(0))
    po_no = po_no or guess_po_number(text)
    po_date = find_po_date(text)

    def locate(line):
        """(mặt hàng, [(đầu, cuối)] các đoạn chữ của mã/tên/quy cách để loại khỏi phần số)."""
        for it in catalog_items:
            code = str(it.get("code") or "").strip()
            if len(code) >= 4:
                ix = line.find(code)
                if ix >= 0:
                    dims, _ = _name_dims(it.get("name"))
                    m = re.search(_dims_regex(dims), line, re.I) if len(dims) >= 2 else None
                    return it, [(ix, ix + len(code))] + ([m.span()] if m else [])
        flat = clean_str(line)
        for it in sorted(catalog_items, key=lambda x: -len(clean_str(x.get("name")))):
            ck = clean_str(it.get("name"))
            if len(ck) >= 6 and ck in flat:
                seen, start, end, target = 0, 0, len(line), flat.find(ck)
                for i, ch in enumerate(line):
                    if re.match(r"[a-z0-9]", clean_str(ch) or "#"):
                        if seen == target:
                            start = i
                        seen += 1
                        if seen == target + len(ck):
                            end = i + 1
                            break
                return it, [(start, end)]
        # Mã dài (>= 10 số) OCR sai 1 chữ số: nhận nếu chỉ đúng 1 mã trong danh mục lệch 1 chữ số
        for tok in re.finditer(r"\d{10,}", line):
            near = [it for it in catalog_items if len(str(it.get("code") or "").strip()) == len(tok.group(0))
                    and sum(a != b for a, b in zip(str(it["code"]).strip(), tok.group(0))) == 1]
            if len(near) == 1:
                return near[0], [tok.span()]
        # PO không có mã/tên giống Invoice (VD hợp đồng tiếng Trung): khớp theo quy cách 38*5*467 (+ định lượng 250g)
        hits = []
        for it in catalog_items:
            dims, gram = _name_dims(it.get("name"))
            if len(dims) < 2:
                continue
            m = re.search(_dims_regex(dims), line, re.I)
            if m:
                hits.append((it, gram, m.span()))
        if hits:
            spans = [h[2] for h in hits]
            grams = [h for h in hits if h[1] and re.search(r"(?<!\d)" + h[1] + r"\s*g", line, re.I)]
            if len(grams) == 1:
                return grams[0][0], spans + [re.search(r"(?<!\d)" + grams[0][1] + r"\s*g", line, re.I).span()]
            return [h[0] for h in hits], spans
        return None, []

    ref_pats = profile.get("lineRefs") or {}
    lines = []
    for raw in (text or "").splitlines():
        # Mã tham chiếu trên dòng PO (Inquiry No, Customs No, mã vật liệu): ghi lại rồi loại khỏi phần số
        refs, ref_spans = {}, []
        for ref_key, ref_pat in ref_pats.items():
            m = re.search(ref_pat, raw)
            if m:
                refs[ref_key] = re.sub(r"\s+", "", m.group(0))
                if ref_key == "customsNo":
                    refs[ref_key] = re.sub(r"^P[a-z]+ing", "Packing", refs[ref_key])
                ref_spans.append(m.span())
        loose = _loose_po_line(raw, catalog_items, ref_spans) if profile.get("ocrLoose") else None
        if loose:
            known, qty, price = loose
        else:
            known, spans = locate(raw)
            if not known:
                continue
            spans = list(spans) + ref_spans
            rest = raw
            for a_, b_ in sorted(set(spans), reverse=True):
                rest = rest[:a_] + " " * (b_ - a_) + rest[b_:]  # giữ nguyên độ dài để các đoạn khác không lệch
            rest = _normalize_ocr_numbers(rest)
            rest = re.sub(r"\d{10,}", " ", rest)  # mã hàng / mã vạch, không phải số lượng
            nums = [parse_vn_number(x) for x in re.findall(r"\d[\d.,]*\d|\d", rest)]
            nums = [n for n in nums if n]
            if isinstance(known, list):
                # nhiều mặt hàng cùng quy cách (VD 250g / 280g): chọn mặt hàng có giá đã học gần giá trên PO nhất
                cand = []
                for it in known:
                    q, p, conf = _qty_price_from_numbers(nums, it.get("price") or 0)
                    if q and p:
                        cand.append((-conf, abs(p - (it.get("price") or 0)) / max(p, 1), it, q, p))
                if not cand:
                    continue
                _, _, known, qty, price = min(cand, key=lambda c: c[:2])
            else:
                qty, price, _ = _qty_price_from_numbers(nums, known.get("price") or 0)
        if qty <= 0:
            continue
        qty = int(qty) if float(qty).is_integer() else qty
        mem = data_store.get_item_norm(known["name"]) if data_store else None
        div = (mem or {}).get("div") or known.get("div") or profile.get("defaultDiv") or 0
        kg = (mem or {}).get("kg") or known.get("kg") or 0
        kien = math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0
        net = round_half_up(qty * kg, 2) if kg > 0 else 0.0
        gross = round_half_up(net + tare_val, 2) if net > 0 else 0.0
        # Mã vật liệu / Inquiry / Customs No: ưu tiên giá trị đã nhớ (người dùng đã sửa ở Bước 1) hơn chữ OCR
        code = known.get("code") or refs.get("itemCode", "")
        extra = {k: known.get(k) or refs.get(k) for k in ("inquiry", "customsNo") if known.get(k) or refs.get(k)}
        if profile.get("dept"):
            extra["dept"] = profile["dept"]
        lines.append({
            **extra,
            "stt": len(lines) + 1,
            "po": po_no,
            "hs": (mem or {}).get("hs") or known.get("hs", "") or (profile.get("customs") or {}).get("hs", ""),
            "ma_sp": code,
            "ten_sp": known["name"],
            "ten_hq": known.get("ten_hq") or known["name"],
            "unit": known.get("unit") or profile.get("unit", "cái"),
            "qty": qty,
            "price": price,
            "amount": round(qty * price),
            "div": div,
            "kg": kg,
            "kien": kien,
            "net": net,
            "gross": gross,
            "tare": tare_val,
        })
    return po_no, po_date, lines


