def lot_recalc(items, customer, tare_text):
    """Tính lại số kiện, KL tịnh, KL cả bì cho từng dòng (sửa trực tiếp `items`).
    `tare_text`: kg cộng thêm mỗi dòng ("0.02") hoặc phần trăm ("0.08%")."""
    try:
        lot_gross(1.0, tare_text)
        spec = tare_text
    except ValueError:
        spec = "1.0"
    default_div = float(PROFILES.get(customer, {}).get("defaultDiv") or 0)
    for it in items:
        qty = float(it.get("qty", 0))
        div = float(it.get("div", 0)) or default_div
        it["div"] = div
        kg = float(it.get("kg", 0))
        if div > 0:
            it["kien"] = math.ceil(round(qty / div * 1e6) / 1e6)
        if kg > 0:
            it["net"] = round_half_up(qty * kg, 2)
            it["gross"] = lot_gross(it["net"], spec)


def lot_build_record(store, form, items):
    """Dựng hồ sơ (record) từ các ô nhập `form` và danh sách dòng hàng `items`.

    `form` là dict các khóa: customer, doc_date, po, po_date, schedule, pxk, hd, tk,
    luong, xe, driver, ldd, po_dates, pay_days, delivery (chuỗi; thiếu thì coi là rỗng).
    """
    g = lambda k: str(form.get(k) or "").strip()
    cust = g("customer")
    dt = g("doc_date") or datetime.date.today().strftime("%Y-%m-%d")
    tot_qty = sum(float(x.get("qty", 0)) for x in items)
    tot_amt = sum(float(x.get("amount", 0)) for x in items)
    tot_net = sum(float(x.get("net", 0)) for x in items)
    tot_gross = sum(float(x.get("gross", 0)) for x in items)
    tot_kien = sum(float(x.get("kien", 0)) for x in items)
    sched = g("schedule")
    s_key = sched if (cust == "shirai" and sched) else (dt[8:10] + "." + dt[5:7] if len(dt) == 10 else "30.10")
    rec = {
        "id": g("record_id") or f"HS-{dt.replace('-', '')}-{cust.upper()}-{len(store.records)+1:02d}",
        "zone": "WORKING",
        "customer": cust,
        "docDate": dt,
        "poNumber": g("po"),
        "poDate": g("po_date"),
        "scheduleKey": s_key,
        "pxkNo": g("pxk"),
        "hdNo": g("hd"),
        "tkNo": g("tk"),
        "luong": g("luong"),
        "xeNo": g("xe"),
        "driver": g("driver"),
        "lddSeq": g("ldd"),
        "poDates": dict(form.get("po_dates") or {}),
        "payDays": g("pay_days"),
        "deliveryDate": g("delivery"),
        "totalQty": tot_qty,
        "totalAmount": tot_amt,
        "totalNet": round(tot_net, 2),
        "totalGross": round(tot_gross, 2),
        "totalKien": tot_kien,
        "updatedAt": datetime.datetime.now().strftime("%d/%m/%Y %H:%M"),
        "poFiles": [str(x) for x in (form.get("po_files") or []) if x],
        "workedBy": store.user_name(),  # người làm hồ sơ (tên đặt ở Cài đặt của từng máy)
        "items": [dict(x) for x in items],
        "files": {"po": None, "pxk": None, "vat": None, "pkl": None, "tk": None, "scan": None},
    }
    if is_best_docset(PROFILES.get(cust, {})):
        rec["totalKien"] = lot_totals(rec)["kien"]
    return rec


def lot_export(store, rec, mode="ALL", skip_h=False):
    """Xuất Excel cho hồ sơ `rec` vào thư mục làm việc của hồ sơ.

    Trả {"path", "fname", "problems", "dsh"}: `problems` là danh sách điểm lệch khi kiểm tra
    chéo (chỉ mode ALL), `dsh` là tên file danh sách hàng ECUS đi kèm (nếu có).
    Ném ValueError(thông báo tiếng Việt) khi không xuất được.
    """
    if not rec.get("items"):
        raise ValueError("Chưa có dòng hàng nào để xuất file Excel.")
    try:
        store.dt_learn_items(rec["customer"], rec["items"])  # nhớ kg/chiếc, SL/kiện đã xác nhận vào data tổng dùng chung
    except Exception:
        pass
    if mode == "DCCN" and not is_best_docset(rec) and ("DCCN" in customer_extra_docs(PROFILES.get(rec["customer"], {})) or best_template(PROFILES.get(rec["customer"], {}), "dccn")):
        pass  # khách đã học có đối chiếu công nợ riêng
    elif mode in ("BEST", "PACK", "PGH", "DCCN") and not is_best_docset(rec):
        raise ValueError("Khách này chưa đặt bộ mẫu 'best'. Thêm khách bằng nút 'Thêm Khách Mới' và chọn bộ mẫu best.")
    if mode == "SO" and rec["customer"] != "shirai":
        raise ValueError("Phiếu SO chỉ dùng cho khách Shirai.")
    if mode == "B11" and not (rec["customer"] == "tesa" or PROFILES.get(rec["customer"], {}).get("customs")):
        raise ValueError("Khách này chưa có thông tin tờ khai B11.")
    folder = store.get_record_folder_path(rec)
    work_dir = os.path.join(folder, GENERATED_DIR)
    os.makedirs(work_dir, exist_ok=True)
    for src in rec.get("poFiles") or []:  # PO gốc khách gửi: lưu cùng chứng từ đã tạo
        try:
            dst = os.path.join(work_dir, "PO_goc_" + os.path.basename(src))
            if os.path.isfile(src) and not os.path.exists(dst):
                shutil.copy2(src, dst)
        except OSError:
            pass
    clean_po = re.sub(r"[^a-zA-Z0-9_-]", "", rec["poNumber"])[:24]
    s_key = rec.get("scheduleKey", "30.10")
    problems = []

    wb = openpyxl.Workbook()
    wb.remove(wb.active)

    if mode == "VAT":
        build_vat_bkav_sheet(wb, rec, s_key)
        fname = f"Hoa_Don_VAT_BKAV_{rec['customer']}_{s_key}.xlsx"
    elif mode == "PKL":
        build_invoice_pkl_sheet(wb, rec, s_key, skip_h=skip_h)
        fname = f"invoice_{rec['customer']}_{rec['pxkNo'] or '0000294'}_{s_key}.xlsx"
    elif mode == "PXK":
        build_pxk_bkav_sheet(wb, rec, s_key)
        fname = f"PXK_KVCNB_BKAV_{rec['customer']}_{s_key}.xlsx"
    elif mode == "DNTT":
        build_dntt_sheet(wb, rec, "DNTT")
        fname = f"DNTT_{rec['customer']}_{s_key}.xlsx"
    elif mode == "PLX":
        build_plx_sheet(wb, rec, f"PLX_{s_key}")
        fname = f"PLX_{rec['customer']}_{s_key}.xlsx"
    elif mode == "BBGH":
        build_bbgh_sheet(wb, rec, f"BBGH_{s_key}")
        fname = f"BienBanBanGiao_{rec['customer']}_{s_key}.xlsx"
    elif mode == "BEST":
        build_packing_best_sheet(wb, rec, f"DongGoi_{s_key}")
        build_pgh_best_sheet(wb, rec, f"PGH_{s_key}")
        build_dccn_best_sheet(wb, rec, f"DCCN_{s_key}")
        build_dntt_sheet(wb, rec, "DNTT")
        fname = f"Mau_Best_{rec['customer']}_{clean_po}_{s_key}.xlsx"
    elif mode == "DSH":
        build_ecus_dsh_sheet(wb, rec)
        fname = f"dsh_{rec['pxkNo'] or rec['customer']}.xlsx"
    elif mode == "SO":
        build_so_shirai_sheet(wb, rec, f"SO_{clean_po}_{s_key}")
        fname = f"SO_{rec['customer']}_{clean_po}_{s_key}.xlsx"
    elif mode == "B11":
        build_customs_b11_sheet(wb, rec, f"ToKhai_B11_{s_key}")
        fname = f"ToKhai_B11_{rec['customer']}_{s_key}.xlsx"
    elif mode == "PACK":
        build_packing_best_sheet(wb, rec, f"DongGoi_{s_key}")
        fname = f"DongGoi_{rec['customer']}_{s_key}.xlsx"
    elif mode == "PGH":
        build_pgh_best_sheet(wb, rec, f"PGH_{s_key}")
        fname = f"PhieuGiaoHang_{rec['customer']}_{s_key}.xlsx"
    elif mode == "DCCN":
        build_dccn_best_sheet(wb, rec, f"DCCN_{s_key}")
        fname = f"DoiChieuCongNo_{rec['customer']}_{s_key}.xlsx"
    elif mode == "CHECK":
        problems = check_lot(rec)
        build_check_sheet(wb, rec, problems, f"KiemTra_{s_key}")
        fname = f"KiemTraCheo_{rec['customer']}_{s_key}.xlsx"
    else:
        build_full_bundle(wb, rec, s_key, skip_h=skip_h)
        problems = check_lot(rec)
        build_check_sheet(wb, rec, problems, f"KiemTra_{s_key}")
        fname = f"Bo_Ho_So_Xuat_Hang_{PROFILES[rec['customer']]['label']}_{clean_po}_{s_key}.xlsx"

    out_path = os.path.join(work_dir, fname)
    if mau_chung_tu:
        mau_chung_tu.autofit_workbook(wb)  # chữ dài tự xuống dòng, dòng tự cao, cột số vừa đủ: mở ra là in được
    wb.save(out_path)
    dsh = None
    if mode == "ALL" and rec["customer"] not in BUILTIN_CUSTOMERS:
        # Danh sách hàng để import ECUS đi kèm trọn bộ của khách mới
        wb_dsh = openpyxl.Workbook()
        wb_dsh.remove(wb_dsh.active)
        build_ecus_dsh_sheet(wb_dsh, rec)
        dsh = f"dsh_{rec['pxkNo'] or rec['customer']}.xlsx"
        wb_dsh.save(os.path.join(work_dir, dsh))
    return {"path": out_path, "fname": fname, "problems": problems, "dsh": dsh}


LOT_MODE_LABELS = {
    "SO": "Phiếu SO", "PKL": "Invoice / Packing List", "PACK": "Chi tiết đóng gói", "VAT": "Hóa đơn VAT", "PXK": "Phiếu xuất kho",
    "B11": "Tờ khai B11", "PLX": "Phụ lục X", "PGH": "Phiếu giao hàng", "DCCN": "Đối chiếu công nợ", "DNTT": "Đề nghị thanh toán",
    "DSH": "Danh sách hàng ECUS", "CHECK": "Kiểm tra chéo", "BBGH": "Biên bản bàn giao",
}


def lot_bundle_modes(rec):
    """Các chứng từ thuộc 'trọn bộ' của khách (cùng thành phần với build_full_bundle), theo thứ tự làm việc.
    Khách đã học (không phải Best): mặc định chỉ Invoice + Hóa đơn VAT + Phiếu xuất kho, thêm gì theo mục 'Chứng từ làm thêm' của khách."""
    cust = rec["customer"]
    prof = PROFILES.get(cust, PROFILES["shirai"])
    best = is_best_docset(prof)
    if cust not in BUILTIN_CUSTOMERS and not best:
        return ["PKL", "VAT", "PXK"] + customer_extra_docs(prof)
    modes = ["SO"] if cust == "shirai" else []
    modes.append("PKL")
    if best:
        modes.append("PACK")
    modes += ["VAT", "PXK"]
    if cust == "tesa":
        modes += ["B11", "PLX"]
    elif prof.get("customs"):
        modes.append("B11")
    if best:
        modes += ["PGH", "DCCN"]
    modes.append("DNTT")
    if cust not in BUILTIN_CUSTOMERS:
        modes.append("DSH")
    modes.append("CHECK")
    return modes


def lot_export_each(store, rec, skip_h=False):
    """Xuất trọn bộ nhưng MỖI CHỨNG TỪ MỘT FILE Excel riêng (cùng thư mục hồ sơ).
    Trả {"files": [{"mode", "label", "name", "path"}], "problems": [điểm lệch khi kiểm tra chéo]}."""
    files = []
    for mode in lot_bundle_modes(rec):
        res = lot_export(store, rec, mode, skip_h=skip_h)
        files.append({"mode": mode, "label": LOT_MODE_LABELS[mode], "name": res["fname"], "path": res["path"]})
    return {"files": files, "problems": check_lot(rec)}


def lot_save_new(store, rec, exported_files):
    """Lưu hồ sơ vừa làm ở Bước 1: gắn các file đã xuất, ghi đè hồ sơ cùng khách + cùng số PO."""
    store.sync()  # máy khác có thể vừa lưu hồ sơ vào thư mục dùng chung
    for k, v in exported_files.items():
        rec["files"][k] = v
    if not rec.get("folder"):  # nhớ thư mục để mở lại đúng chỗ dù sau này đổi tên gọi khách
        folder = store.get_record_folder_path(rec)
        rr = os.path.relpath(folder, store.customs_root())
        if not rr.startswith(".."):
            rec["folder"] = os.path.join(CUSTOMS_ROOT, rr)
    idx = store.find_record(rec)
    if idx >= 0:
        for k, v in store.records[idx].get("files", {}).items():
            if v and not rec["files"].get(k):
                rec["files"][k] = v
        rec["id"] = store.records[idx]["id"]
        if store.records[idx].get("folder"):
            rec["folder"] = store.records[idx]["folder"]
        store.records[idx] = rec
    else:
        store.records.insert(0, rec)
    store.save_records()
    return rec


def lot_save_workbench(store, rec):
    """Lưu hồ sơ ở Bước 2: ghi file 00_HO_SO_<id>.json vào thư mục hồ sơ và cập nhật danh sách."""
    store.sync()
    dest_dir = store.get_record_folder_path(rec)
    os.makedirs(dest_dir, exist_ok=True)
    with open(os.path.join(dest_dir, f"00_HO_SO_{rec['id']}.json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=2)
    idx = next((i for i, r in enumerate(store.records) if r["id"] == rec["id"]), -1)
    if idx >= 0:
        store.records[idx] = rec
    else:
        store.records.insert(0, rec)
    store.save_records()
    return dest_dir


def lot_merge_dates(schedules, keys):
    """Gộp các dòng hàng của những ngày giao đã chọn, giữ đúng thứ tự dòng trong PO. Trả danh sách dòng mới (bản sao)."""
    rows = [dict(it) for k in keys if k in schedules for it in schedules[k]["items"]]
    rows.sort(key=lambda it: it.get("po_seq", 0))
    for i, it in enumerate(rows, 1):
        it["stt"] = i
    return rows


def lot_defaults(customer):
    """Giá trị mặc định các ô nhập khi chọn khách (xe, tài xế, bì, hạn thanh toán…)."""
    prof = PROFILES.get(customer, PROFILES["shirai"])
    if customer in BUILTIN_CUSTOMERS:
        tare = "0.0" if customer == "tesa" else ("0.02" if customer == "shirai" else "1.0")
    else:
        tare = str(prof.get("tare", 0.0))
    return {
        "xe": prof["xe"], "driver": prof["driver"], "ldd": prof["lenhSeq"], "tare": tare,
        "pay_days": str(prof.get("payDays", 30)), "delivery": "", "luong": "Xanh",
    }


_MONEY = re.compile(r"^\d{1,3}(?:,\d{3})*\.\d{2}$")


def _runs(flags, gap=6):
    out = []
    for y, f in enumerate(flags):
        if f:
            if out and y - out[-1][-1] <= gap:
                out[-1].append(y)
            else:
                out.append([y])
    return [int(sum(r) / len(r)) for r in out]


def read_best_po_table(path, catalog_items):
    """PO Best scan (mẫu in từ ERP): tìm các đường kẻ của bảng rồi đọc từng ô ở độ nét cao. Đọc cả trang hay làm mất dấu
    thập phân (1,200.00 -> 120000) hoặc dính hai số vào nhau. Trả [{name, code, qty, price, amount, inquiry}] hoặc [] nếu
    không chắc (không thấy bảng, không nhận ra mặt hàng, SL x giá khác thành tiền) để quay về cách đọc cũ."""
    if pdfium is None or pytesseract is None:
        return []
    try:
        img = auto_rotate_scan(pdfium.PdfDocument(path)[0].render(scale=4.5).to_pil()).convert("L")
    except Exception:
        return []
    W, H = img.size
    x0, x1 = int(W * 0.04), int(W * 0.93)
    ys = _runs([v > 0.3 for v in po_scan.dark_profile(img, 0, 140, (x0, 0, x1, H))])  # đường kẻ ngang (Pillow, không cần numpy: bản .exe bỏ numpy)
    if len(ys) < 3:
        return []
    diffs = sorted(b - a for a, b in zip(ys, ys[1:]))
    pitch = diffs[len(diffs) // 2]
    run = [ys[0]]
    for y in ys[1:]:  # đoạn đường kẻ cách đều từ đầu bảng (viền trên, đáy tiêu đề, các dòng hàng)
        if abs(y - run[-1] - pitch) <= pitch * 0.12:
            run.append(y)
        elif y - run[-1] > pitch * 1.5 and len(run) >= 3:
            break
        elif len(run) < 3:
            run = [y]
    if len(run) < 3:
        return []
    xs = _runs([v > 0.8 for v in po_scan.dark_profile(img, 1, 140, (0, run[1] + 10, W, run[2] - 10))])  # đường kẻ dọc
    if len(xs) < 10:
        xs = [int(W * f) for f in (0.036, 0.059, 0.117, 0.23, 0.349, 0.393, 0.427, 0.475, 0.532, 0.608)]
    col = {"spec": (xs[3], xs[4]), "qty": (xs[4], xs[5]), "price": (xs[6], xs[7]), "amount": (xs[7], xs[8]), "inquiry": (xs[8], xs[9])}

    def cell(key, y0, y1, cfg):
        a, b = col[key]
        c = img.crop((a + 12, y0 + 10, b - 12, y1 - 10))
        c = c.resize((int(c.width * 1.5), int(c.height * 1.5)))
        return pytesseract.image_to_string(c, lang="eng", config=cfg).strip()

    num = "--psm 7 -c tessedit_char_whitelist=0123456789,."

    def money(t):  # OCR đọc sai dấu: '600,00', '7,684,200,00', '7471100.00'
        t = t.strip().strip(",.")
        t = re.sub(r",(\d{2})$", r".\1", t).replace(",", "")
        return float(t) if re.fullmatch(r"\d+\.\d{2}", t) else None

    def close(a, b):  # cùng độ dài, lệch tối đa 1 chữ số (OCR nhầm 0/3, 6/8...)
        a, b = str(int(a)), str(int(b))
        return len(a) == len(b) and sum(x != y for x, y in zip(a, b)) <= 1

    rows = []
    for y0, y1 in zip(run[1:-1], run[2:]):
        q, p, am = (money(cell(k, y0, y1, num)) for k in ("qty", "price", "amount"))
        nums = re.findall(r"\d+(?:\.\d+)?", cell("spec", y0, y1, "--psm 7"))
        item = next((it for it in catalog_items if len(nums) >= 3 and _name_dims(it.get("name"))[0][1:] == nums[-2:]), None)
        if item is None and p:  # quy cách đọc hỏng: nhận mặt hàng theo đơn giá đã học
            item = next((it for it in catalog_items if it.get("price") and close(it["price"], p)), None)
        if q and not am and item and p and close(p, item.get("price") or 0):
            am = q * float(item["price"])  # ô thành tiền hỏng nhưng SL và đơn giá khớp đơn giá đã học
        if not (q and am and item):
            return []
        qty = price = 0
        for pc in [x for x in (p, item.get("price")) if x]:  # đơn giá OCR hoặc đơn giá đã học: lấy cái cho SL x giá = thành tiền
            for qc in (q, am / pc):
                if qc > 0 and abs(qc - round(qc)) < 1e-9 and abs(round(qc) * pc - am) <= 1:
                    qty, price = int(round(qc)), int(pc)
                    break
            if qty:
                break
        if not qty:
            return []
        inq = re.findall(r"Q[^\d\s]{0,2}(\d{10,11})(?!\d)", cell("inquiry", y0, y1, "--psm 7 -c tessedit_char_whitelist=QS0123456789"))
        rows.append({"name": item["name"], "code": item.get("code") or "", "qty": qty, "price": price, "amount": int(am),
                     "inquiry": ("QS" + inq[0][-10:]) if inq else ""})
    return rows


def fix_inquiries_from_scan(path, lines):
    """PO scan: OCR cỡ thường hay đọc nhầm số Inquiry (QS2603000725 -> QS3603000735). Đọc lại ở độ nét cao,
    chỉ lấy các mã QS...; đủ bằng số dòng hàng thì gán theo thứ tự dòng. PDF có chữ sẵn thì bỏ qua (đã chính xác)."""
    if pypdf is None or pdfium is None or pytesseract is None:
        return
    try:
        if len(re.sub(r"\s+", "", pypdf.PdfReader(path).pages[0].extract_text() or "")) > 80:
            return
        img = auto_rotate_scan(pdfium.PdfDocument(path)[0].render(scale=4.5).to_pil())
        txt = pytesseract.image_to_string(img, lang="vie+eng", config="--psm 4")
    except Exception:
        return
    found = [m.group(1)[-10:] for m in re.finditer(r"Q[^\d\s]{0,2}\s?(\d{10,11})(?!\d)", txt)]  # 'QS82603000725': OCR thêm 1 số 8 sau chữ S
    if len(found) == len(lines):
        top = max(set(found), key=found.count)  # mã nhiều dòng dùng chung; dòng lệch đúng 1 chữ số so với mã đó là OCR đọc nhầm
        found = [top if f != top and found.count(top) >= 3 and sum(x != y for x, y in zip(f, top)) == 1 else f for f in found]
        for ln, num in zip(lines, found):
            ln["inquiry"] = "QS" + num


def _pdf_has_text(path):
    try:
        return len(re.sub(r"\s+", "", pypdf.PdfReader(path).pages[0].extract_text() or "")) > 80
    except Exception:
        return False


def best_scan_lines(path, prof, store, po_no, po_date, tare_v):
    """Dòng hàng của PO Best scan đọc theo từng ô của bảng; dựng lại thành chữ sạch rồi cho bộ đọc PO chung xử lý
    (cùng cách tính kiện, tịnh, cả bì như mọi PO khác). Trả [] nếu không đọc chắc để quay về cách đọc cả trang."""
    catalog = store.items_for_customer(prof["key"])
    rows = read_best_po_table(path, catalog)
    if not rows:
        return []
    d = re.match(r"(\d{2})/(\d{2})/(\d{4})", po_date or "")
    text = f"PO No: {po_no}\n" + (f"PO Date {d.group(3)}/{d.group(2)}/{d.group(1)}\n" if d else "")
    for i, r in enumerate(rows, 1):
        text += (f"{i} | {r['code']} {r['name']} {r['qty']:,.2f} PCS {r['price']:,.2f} {r['amount']:,.2f} {r['inquiry']} "
                 f"PRS0000000000 PackingF001 QC VAI\n")
    _, _, lines = parse_generic_po_text(text, prof, catalog, data_store=store, tare_val=tare_v)
    return lines if len(lines) == len(rows) else []


def lot_load_po(store, path, customer, tare_text="", existing_items=None, append=False, po_dates=None, progress=None):
    """Đọc file PO của khách `customer` (offline). Không đụng giao diện.

    Trả dict: ok, msg (tiếng Việt), customer (có thể đổi theo nhận dạng file), po, po_date, po_dates,
    items, và với Shirai: schedules {khóa: {dateStr, items}}, schedule_key, doc_date.
    Ném ValueError khi yêu cầu không hợp lệ (vd gộp PO cho khách có sẵn).
    """
    existing_items = list(existing_items or [])
    po_dates = dict(po_dates or {})
    res = {"ok": False, "msg": "", "customer": customer, "po": "", "po_date": "", "po_dates": po_dates,
           "items": existing_items, "schedules": None, "schedule_key": "", "doc_date": ""}
    if append and customer in BUILTIN_CUSTOMERS:
        raise ValueError("Gộp nhiều PO vào một lô dùng cho khách đã học (VD Best). Shirai/Kodi/Tesa giữ cách quét cũ.")
    ext = os.path.splitext(path)[1].lower()

    if customer not in BUILTIN_CUSTOMERS:
        prof = PROFILES[customer]
        try:
            tare_v = float(tare_text or 0.0)
        except Exception:
            tare_v = 0.0
        scan_rep = None
        scan_ok = ext == ".pdf" and po_scan is not None and not _pdf_has_text(path)
        if scan_ok and is_able(prof):
            scan_rep = po_scan.read_able_pdf(sys.modules[__name__], path, store.items_for_customer(customer), progress=progress)  # PO scan: đọc từng ô của bảng, mỗi trang một PO
        elif scan_ok and prof.get("poGrid") == "cn_erp":  # PO scan kiểu ERP chữ Hán (AVG): 9 cột, đọc từng ô
            scan_rep = po_scan.read_cn_erp_pdf(sys.modules[__name__], path, store.items_for_customer(customer), prof.get("po_pattern", ""), progress=progress)
        raw_text = "" if (scan_rep and scan_rep["rows"]) else read_document_text(path)  # đọc được theo ô rồi thì khỏi OCR cả trang
        po_no, po_date, lines = parse_generic_po_text(raw_text, prof, store.items_for_customer(customer), data_store=store, tare_val=tare_v)
        pcs_rows = parse_pcs_note_rows(raw_text)
        able_rows = [] if pcs_rows or not is_able(prof) else parse_able_po_rows(raw_text, store.items_for_customer(customer))
        table_rows = parse_excel_table_po(path) if ext in (".xlsx", ".xlsm") else []
        if table_rows:  # PO Excel dạng bảng: đọc đúng từng cột, bỏ dòng mẫu trống, mỗi dòng ghép mặt hàng theo mã khách trong ngoặc hoặc loại hàng + kích thước
            lines = lines_from_excel_table(table_rows, po_no, prof, store.items_for_customer(customer), data_store=store, tare_val=tare_v)
            pcs_rows = []
        dated_rows = [] if (pcs_rows or able_rows or table_rows) else parse_dated_unit_rows(raw_text)
        labelled = find_po_after_label(raw_text)
        if labelled and (dated_rows or table_rows) and not _po_pattern_hits(prof, raw_text, po_no):
            po_no = labelled  # số PO ghi sau nhãn 'mã PO' / '采购订单编号'; mẫu nhận dạng đã học không khớp thì không tin số đoán được
        if dated_rows:  # PO chữ Hán: tra tên/mã theo mã liệu + quy cách trong danh mục khách rồi danh mục ERP
            cat = store.items_for_customer(customer)
            resolved = [resolve_po_item(r, cat, store.erp_catalog) for r in dated_rows]
            rows2 = [{"code": rv["code"] or r["code"], "desc": rv["name"] or r["desc"], "qty": r["qty"], "price": r["price"], "ship": r["ship"], "_known": rv["item"] or {}}
                     for r, rv in zip(dated_rows, resolved)]
            lines = lines_from_erp_rows(rows2, po_no, prof, cat, data_store=store, tare_val=tare_v)
            for ln, rv in zip(lines, resolved):
                if rv["code"]:
                    ln["ma_sp"] = rv["code"]  # mã liệu ghi trên PO là mã khách dùng; mã học trước đó có thể là mã nội bộ khác
                if rv["src"] == "erp":
                    ln["read"], ln["read_note"] = "suy_ra", "Tên lấy từ danh mục ERP theo mã liệu/quy cách; chưa có kg, SL/kiện của khách"
                elif not rv["src"]:
                    ln["read"], ln["read_note"] = "suy_ra", "Chưa tìm được tên trong danh mục: kiểm tra mã liệu, quy cách"
            pcs_rows = []
        erp_rows = [] if (table_rows or dated_rows) else (pcs_rows or able_rows or erp_rows_repaired(raw_text, store.items_for_customer(customer)))
        if pcs_rows:  # PO kiểu Quang Ích: dòng hàng kèm ngày giao và đơn giá ở cột ghi chú
            pass
        if scan_rep and scan_rep["rows"]:
            lines = lines_from_able_scan(scan_rep["rows"], prof, store.items_for_customer(customer), store, tare_v)
            po_no = lines[0].get("po") or po_no
            res["read_report"] = read_report(lines, scan_rep.get("check", ""))
        elif erp_rows:  # PO in từ ERP có lớp chữ: đọc đúng từng cột, không đoán SL/giá từ cả dòng
            lines = lines_from_erp_rows(erp_rows, po_no, prof, store.items_for_customer(customer), data_store=store, tare_val=tare_v)
        elif lines and ext == ".pdf" and "inquiry" in (prof.get("lineRefs") or {}) and not _pdf_has_text(path):
            lines = best_scan_lines(path, prof, store, po_no, po_date, tare_v) or (fix_inquiries_from_scan(path, lines) or lines)
        if able_rows and lines and not (scan_rep and scan_rep["rows"]):
            for ln in lines:
                ln.setdefault("read", "ok")  # PO có lớp chữ: SL x giá đã đối chiếu thành tiền khi đọc
        if not lines and scan_ok and not (scan_rep and scan_rep["rows"]):  # đọc cả trang không ra dòng nào: thử đọc theo ô bảng ERP chữ Hán
            scan_rep = po_scan.read_cn_erp_pdf(sys.modules[__name__], path, store.items_for_customer(customer), prof.get("po_pattern", ""), progress=progress)
            if scan_rep["rows"]:
                lines = lines_from_able_scan(scan_rep["rows"], prof, store.items_for_customer(customer), store, tare_v)
                po_no = lines[0].get("po") or po_no
                res["read_report"] = read_report(lines, scan_rep.get("check", ""))
        if lines:
            store.dt_fill_lines(customer, lines)  # thiếu kg/chiếc hoặc SL/kiện: lấy từ data tổng dùng chung
        if not lines:
            res["msg"] = "Không tìm thấy dòng hàng nào khớp mã/tên hàng đã học. Hãy thêm dòng trực tiếp, hoặc nạp thêm chứng từ mẫu cho khách này."
            return res
        if append and existing_items:
            if po_no and po_no in {str(x.get("po") or "") for x in existing_items}:
                res["msg"] = f"PO {po_no} đã có trong lô này, không gộp lần nữa."
                return res
            items = existing_items + lines
        else:
            items, po_dates = lines, {}
            if po_date:
                res["po_date"] = po_date
        if po_no:
            po_dates[po_no] = po_date or po_dates.get(po_no, "")
        pos = []
        for x in items:
            p = str(x.get("po") or "")
            if p and p not in pos:
                pos.append(p)
        res.update(ok=True, items=items, po_dates=po_dates, po=" + ".join(pos) if pos else po_no, raw_text=raw_text)
        res["msg"] = (f"Đã gộp PO {po_no} ({len(lines)} dòng) vào lô: {len(pos)} PO, {len(items)} dòng."
                      if append else f"Đã đọc PO {po_no or '(chưa rõ số)'} gồm {len(lines)} dòng hàng.")
        if res.get("read_report"):
            res["msg"] = res["read_report"]["text"]
        return res

    if ext in (".xlsx", ".xls"):
        po_no, schedules = parse_shirai_po_excel(path, store, tare_text or "0.02")
        if schedules:
            keys = list(schedules.keys())
            res.update(ok=True, customer="shirai", po=po_no, schedules=schedules, schedule_key="",
                       items=lot_merge_dates(schedules, keys),
                       msg=f"Đã bóc tách PO {po_no}: {sum(len(v['items']) for v in schedules.values())} dòng, "
                           f"{len(keys)} ngày giao ({', '.join(keys)}). Mặc định làm một invoice cho cả PO; bỏ tích ngày nào chưa khai.")
            return res

    raw_txt = extract_text_from_pdf_or_image_offline(path, is_tesa=(customer == "tesa"))
    if customer == "tesa" or "8600" in raw_txt:
        po_no, lines = parse_tesa_po_text(raw_txt, store.tesa_items, data_store=store)
        if lines:
            res.update(ok=True, customer="tesa", items=lines, po=f"{po_no}.. ({len(lines)} PO)" if len(lines) > 1 else po_no,
                       msg=f"Đã đọc {len(lines)} PO Tesa từ trang chẵn hoàn toàn offline.")
            return res
    try:
        tare_v = float(tare_text or 1.0)
    except Exception:
        tare_v = 1.0
    po_no, po_date, lines = parse_kodi_po_text(raw_txt, store.kodi_items, data_store=store, tare_val=tare_v)
    if lines:
        res.update(ok=True, customer="kodi", items=lines, po=po_no or "", po_date=po_date or "",
                   msg=f"Đã bóc tách PO {po_no} ({len(lines)} dòng hàng) hoàn toàn offline.")
        return res
    res["msg"] = ("Không tìm thấy dòng hàng trong file (kể cả sau khi OCR ảnh scan). Bản scan có thể mờ/nghiêng; bạn có thể thêm dòng trực tiếp."
                  if ocr_available() else
                  "File PDF là ảnh scan chưa có lớp chữ nhúng và máy chưa có bộ OCR (thư mục Tesseract-OCR cạnh file .exe). Bạn có thể thêm dòng trực tiếp.")
    return res


def lot_item_defaults(customer, po="", tare_text="1.0"):
    """Dòng hàng trống để người dùng điền khi bấm 'Thêm dòng'."""
    prof = PROFILES[customer]
    try:
        tare = float(tare_text or 1.0)
    except Exception:
        tare = 1.0
    return {"po": po, "hs": "48229090", "ma_sp": "", "ten_sp": "", "unit": prof["unit"], "qty": 1000, "price": 0,
            "div": prof.get("defaultDiv") or 0, "kg": 0, "tare": tare}


def lot_lookup_code(store, customer, code):
    """Tra mã hàng trong danh mục Tesa / khách đã học; trả dict điền sẵn (tên, HS, ĐVT, giá, SL/kiện, kg) hoặc None."""
    code = (code or "").strip()
    hit = next((x for x in store.tesa_items + store.custom_items.get(customer, []) if code and x.get("code") == code), None)
    if not hit:
        return None
    mem = store.get_item_norm(hit["name"])
    return {"ten_sp": hit["name"], "hs": hit.get("hs", "48229090"), "unit": hit.get("unit", "ống"),
            "price": hit.get("price", 0), "div": mem["div"] if mem else hit.get("div", 0), "kg": mem["kg"] if mem else hit.get("kg", 0)}


def lot_item_from_values(store, customer, vals, tare_text="1.0", base=None):
    """Dựng một dòng hàng từ các ô nhập `vals` (chuỗi), tính kiện/tịnh/cả bì và NHỚ định mức cho lần sau.
    `base`: dòng cũ khi sửa (giữ các trường không có ô nhập). Ném ValueError nếu số không hợp lệ."""
    g = lambda k: str(vals.get(k) or "").strip()
    try:
        qty, price, div, kg = (float(g(k).replace(",", "") or 0) for k in ("qty", "price", "div", "kg"))
        tare_spec = str(tare_text).strip() or "1.0"
        lot_gross(1.0, tare_spec)
    except ValueError:
        raise ValueError("Số lượng, đơn giá, SL/kiện, kg/chiếc và bì phải là số.")
    if not g("ten_sp"):
        raise ValueError("Chưa nhập tên hàng hóa.")
    best = is_best_docset(PROFILES[customer])
    name, hs, code = g("ten_sp"), g("hs"), g("ma_sp")
    kien = math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0
    net = round_half_up(qty * kg, 2) if kg > 0 else 0.0
    gross = lot_gross(net, tare_spec)
    store.remember_item_norm(name, div, kg, hs)
    if customer not in BUILTIN_CUSTOMERS:
        store.remember_item_refs(customer, name, {"code": code, **{k: g(k) for k in ("inquiry", "customsNo") if k in vals}})
    hit = next((x for x in store.tesa_items if x["name"] == name or x["code"] == code), None)
    item = dict(base) if base else {}
    item.update({k: g(k) for k in ("inquiry", "customsNo") if k in vals})
    if best and not item.get("dept"):
        item["dept"] = PROFILES[customer].get("dept", "")
    num = lambda v: int(v) if v == int(v) else v
    item.update({"po": g("po"), "hs": hs, "ma_sp": code, "ten_sp": name, "ten_hq": (hit.get("ten_hq") if hit else "") or name,
                 "unit": g("unit"), "qty": num(qty), "price": num(price), "amount": round(qty * price), "div": div,
                 "kg": kg, "kien": kien, "net": net, "gross": gross, "tare": 0.0 if tare_spec.endswith("%") else _tare_number(tare_spec, 1.0)})
    return item


def export_master_log(store, path=None):
    """Sổ theo dõi hồ sơ hải quan ra Excel (mọi hồ sơ đã lưu). Trả đường dẫn file."""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "So_Theo_Doi_Ho_So"
    heads = ["STT", "Phân vùng", "Khách hàng", "Ngày CT", "Số PO", "Số PXK", "Số hóa đơn VAT", "Số tờ khai", "Luồng", "Thành tiền (VNĐ)",
             "Cả bì / Tịnh (kg)", "File đã nạp", "Thư mục"]
    for i, h in enumerate(heads, 1):
        c = ws.cell(row=1, column=i, value=h)
        c.font = Font(name="Arial", size=10.5, bold=True, color="FFFFFF")
        c.fill = make_fill("1B365D")
        ws.column_dimensions[get_column_letter(i)].width = 18 if i < 13 else 55
    for idx, r in enumerate(store.records, 1):
        files = r.get("files") or {}
        cnt = sum(1 for k, _, _ in DOC_SLOTS if files.get(k))
        vals = [idx, r.get("zone", ""), r.get("customer", "").upper(), r.get("docDate", ""), r.get("poNumber", ""), r.get("pxkNo", ""), r.get("hdNo", ""),
                r.get("tkNo", ""), r.get("luong", ""), r.get("totalAmount", 0), f"{r.get('totalGross', 0)}/{r.get('totalNet', 0)}",
                f"{cnt}/{len(DOC_SLOTS)} file", store.get_record_folder_path(r)]
        for c_i, v in enumerate(vals, 1):
            c = ws.cell(row=idx + 1, column=c_i, value=v)
            c.border = BOX_BORDER
            if c_i == 10:
                c.number_format = "#,##0"
    path = path or os.path.join(store.base_dir, f"So_Theo_Doi_Ho_So_{datetime.date.today().strftime('%Y%m%d')}.xlsx")
    wb.save(path)
    return path


def run_self_test():
    """Kiểm tra tự động toàn bộ 3 công ty (Shirai, Kodi, Tesa) và tất cả các sheet xuất ra."""
    store = DedicatedDataStore()
    assert len(store.records) >= 3, "Seed records missing"
    for rec in store.records:
        wb = openpyxl.Workbook()
        wb.remove(wb.active)
        if rec["customer"] == "shirai":
            build_so_shirai_sheet(wb, rec, "SO_202637HT")
        build_invoice_pkl_sheet(wb, rec, "Invoice_PKL", skip_h=False)
        build_vat_bkav_sheet(wb, rec, "VAT_BKAV")
        build_pxk_bkav_sheet(wb, rec, "PXK_BKAV")
        if rec["customer"] == "tesa":
            build_customs_b11_sheet(wb, rec, "ToKhai_B11")
            build_plx_sheet(wb, rec, "PLX")
        build_dntt_sheet(wb, rec, "DNTT")
        out_dir = os.path.join(store.customs_root(), "_KIEM_TRA")
        os.makedirs(out_dir, exist_ok=True)
        out_f = os.path.join(out_dir, f"Test_Full_{rec['customer'].upper()}.xlsx")
        wb.save(out_f)
        print("Verified full workbook for:", rec["customer"], "->", out_f)


OCR_SAMPLE_KODI = """CÔNG TY TNHH KODI NEW MATERIAL VIỆT NAM
ĐƠN ĐẶT HÀNG Số: 03102026 - 01KDHT
Bắc Ninh, ngày 03 tháng 10 năm 2026
1 Ống giấy phi 76 x 9 x 1000mm chiếc 31.500 31.500.000
2 Ống giấy phi 152.4x12x1000mm chiếc 89.700 44.850.000
Tổng cộng 76.350.000"""

OCR_SAMPLE_TESA = """tesa site Hai Phong
Purchase Order: 8600226354
10 136,000 PC 39778-90019-00 26,500.00 100 36,040,000.00
PAPER CORE 33.2X2.65X19MM, BLACK
Net Value: VND 36,040,000.00"""


def make_scanned_pdf(path, pages_text):
    """Tạo PDF chỉ có ảnh (giống bản scan, không có lớp chữ), mỗi phần tử của pages_text là một trang A4 200 dpi."""
    from PIL import Image, ImageDraw, ImageFont

    font = None
    for name in ("arial.ttf", "DejaVuSans.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"):
        try:
            font = ImageFont.truetype(name, 26)
            break
        except OSError:
            continue
    if font is None:
        font = ImageFont.load_default(size=26)
    imgs = []
    for text in pages_text:
        img = Image.new("RGB", (1654, 2339), "white")
        draw = ImageDraw.Draw(img)
        for i, line in enumerate(text.splitlines()):
            draw.text((120, 300 + i * 48), line, fill="black", font=font)
        imgs.append(img)
    imgs[0].save(path, "PDF", resolution=200, save_all=True, append_images=imgs[1:])


def run_ocr_self_test():
    """Kiểm tra OCR PDF scan: PO Kodi 1 trang và PO Tesa 2 trang (đọc trang chẵn) dựng thành ảnh rồi bóc tách lại."""
    assert ocr_available(), "Không chạy được Tesseract OCR (thiếu thư mục Tesseract-OCR cạnh app?)"
    langs = pytesseract.get_languages(config="")
    assert "vie" in langs and "eng" in langs, f"Tesseract thiếu dữ liệu ngôn ngữ vie/eng: {langs}"
    store = DedicatedDataStore()
    with tempfile.TemporaryDirectory() as tmp:
        kodi_pdf = os.path.join(tmp, "kodi_scan.pdf")
        make_scanned_pdf(kodi_pdf, [OCR_SAMPLE_KODI])
        txt = extract_text_from_pdf_or_image_offline(kodi_pdf)
        po, po_date, lines = parse_kodi_po_text(txt, store.kodi_items, store)
        assert po == "03102026-01KDHT", f"Kodi: sai số PO {po!r}\n{txt}"
        assert po_date == "03/10/2026", f"Kodi: sai ngày {po_date!r}"
        assert [(x["qty"], x["amount"]) for x in lines] == [(1000, 31_500_000), (500, 44_850_000)], f"Kodi: sai dòng hàng {lines}\n{txt}"

        tesa_pdf = os.path.join(tmp, "tesa_scan.pdf")
        make_scanned_pdf(tesa_pdf, ["GENERAL TERMS AND CONDITIONS OF PURCHASE", OCR_SAMPLE_TESA])
        txt = extract_text_from_pdf_or_image_offline(tesa_pdf, is_tesa=True)
        first_po, lines = parse_tesa_po_text(txt, store.tesa_items, store)
        assert first_po == "8600226354", f"Tesa: sai số PO {first_po!r}\n{txt}"
        assert [(x["ma_sp"], x["qty"]) for x in lines] == [("39778-90019-00", 136000)], f"Tesa: sai dòng hàng {lines}\n{txt}"
    print("OCR PDF scan OK: Kodi + Tesa")


if __name__ == "__main__":
    if "--self-test" in sys.argv or "--ocr-self-test" in sys.argv:
        try:
            run_ocr_self_test() if "--ocr-self-test" in sys.argv else run_self_test()
        except Exception:
            # Bản .exe không có cửa sổ console: ghi lỗi ra file cạnh app và trả mã lỗi thay vì hiện hộp thoại treo máy.
            import traceback
            err = traceback.format_exc()
            if sys.stderr is not None:
                sys.stderr.write(err)
            with open(os.path.join(get_app_dir(), "SELF_TEST_LOI.txt"), "w", encoding="utf-8") as f:
                f.write(err)
            sys.exit(1)
        sys.exit(0)
    store = DedicatedDataStore()
    try:
        from ui_qt.main_window import run as run_qt
    except ImportError as e:  # thiếu PySide6 khi chạy từ mã nguồn
        sys.stderr.write(f"Thiếu PySide6 nên không mở được giao diện: {e}\nCài bằng: pip install -r requirements.txt\n")
        sys.exit(1)
    sys.exit(run_qt(sys.modules[__name__], store, smoke="--gui-smoke" in sys.argv))
